-- Adds the 490 new AI Research vocabulary entries (sort_order 10-499)
-- expanding that word book from 10 to 500 entries, matching
-- src/data/vocabulary/aiResearch.json exactly. Does not touch the
-- original 10 rows (sort_order 0-9), which were already inserted by
-- 20260805020000_create_word_books_and_vocabulary_items.sql, and does not
-- modify that migration. No ON CONFLICT clause: a duplicate or conflicting
-- id here means the seed data itself is wrong, so the migration must fail
-- loudly rather than silently skip a row.
insert into public.vocabulary_items (
  id, word_book_id, term, chinese_meaning, part_of_speech, english_definition,
  example_sentence, example_translation, tags, ipa, pronunciation_text, sort_order, is_active
)
values
  ('ai-supervised-learning', 'ai-research', 'supervised learning', '监督学习', 'n.', 'A machine learning approach that trains a model on labeled input-output pairs.', 'Supervised learning worked well here because we had thousands of labeled examples.', '由于我们拥有数千个已标注的样本，监督学习在这里效果很好。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 10, true),
  ('ai-unsupervised-learning', 'ai-research', 'unsupervised learning', '无监督学习', 'n.', 'A machine learning approach that finds patterns in data without labeled outputs.', 'Unsupervised learning grouped customers into segments nobody had defined in advance.', '无监督学习把客户自动分成了几个此前没有人预先定义的群体。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 11, true),
  ('ai-semi-supervised-learning', 'ai-research', 'semi-supervised learning', '半监督学习', 'n.', 'A learning approach that uses a small amount of labeled data alongside a large amount of unlabeled data.', 'Semi-supervised learning let us use the ten thousand unlabeled images we hadn''t annotated yet.', '半监督学习让我们能够利用那一万张还没标注的图像。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 12, true),
  ('ai-reinforcement-learning', 'ai-research', 'reinforcement learning', '强化学习', 'n.', 'A learning approach where an agent learns to make decisions by receiving rewards or penalties.', 'Reinforcement learning trained the agent to win the game through millions of trial-and-error episodes.', '强化学习通过数百万次试错让智能体学会了如何赢得这个游戏。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 13, true),
  ('ai-self-supervised-learning', 'ai-research', 'self-supervised learning', '自监督学习', 'n.', 'A learning approach where the model generates its own supervisory signal from unlabeled data.', 'Self-supervised learning let the model pretrain on raw text without any human labels.', '自监督学习让模型能够在没有任何人工标注的情况下，直接用原始文本进行预训练。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 14, true),
  ('ai-feature-engineering', 'ai-research', 'feature engineering', '特征工程', 'n.', 'The process of creating input variables that help a model learn more effectively.', 'Feature engineering added a day-of-week column that turned out to be highly predictive.', '特征工程增加了一个"星期几"的字段，结果证明它有很强的预测能力。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 15, true),
  ('ai-feature-extraction', 'ai-research', 'feature extraction', '特征提取', 'n.', 'The process of transforming raw data into a set of measurable features for a model.', 'Feature extraction from the audio files reduced each clip to just twenty numbers.', '从音频文件中进行的特征提取，把每段音频压缩成了仅二十个数字。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 16, true),
  ('ai-label', 'ai-research', 'label', '标签', 'n.', 'The correct output or category assigned to a piece of training data.', 'Each image in the dataset had a single label indicating which animal it showed.', '数据集中的每张图像都有一个标签，标明了图中是哪种动物。', ARRAY['machine-learning', 'data']::text[], null, null, 17, true),
  ('ai-ground-truth', 'ai-research', 'ground truth', '真实标注（金标准）', 'n.', 'The verified, correct data used as a reference to evaluate a model''s predictions.', 'The model''s predictions were compared against ground truth labeled by human experts.', '模型的预测结果与由人类专家标注的真实标注进行了对比。', ARRAY['machine-learning', 'evaluation']::text[], null, null, 18, true),
  ('ai-loss-function', 'ai-research', 'loss function', '损失函数', 'n.', 'A function that measures how far a model''s predictions are from the true values.', 'Switching the loss function to focal loss helped the model handle rare classes better.', '把损失函数换成 focal loss 后，模型对稀有类别的处理效果更好了。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 19, true),
  ('ai-gradient-descent', 'ai-research', 'gradient descent', '梯度下降', 'n.', 'An optimization algorithm that adjusts model parameters to minimize a loss function.', 'Gradient descent gradually reduced the loss over thousands of training steps.', '梯度下降在数千个训练步骤中逐渐降低了损失值。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 20, true),
  ('ai-backpropagation', 'ai-research', 'backpropagation', '反向传播', 'n.', 'The algorithm used to compute gradients and update weights in a neural network.', 'Backpropagation efficiently computed how much each weight contributed to the error.', '反向传播高效地计算出了每个权重对误差的贡献程度。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 21, true),
  ('ai-learning-rate', 'ai-research', 'learning rate', '学习率', 'n.', 'A hyperparameter that controls how much model weights are adjusted during training.', 'A learning rate that was too high caused the training loss to bounce around instead of decreasing.', '学习率过高导致训练损失不断波动，而不是稳步下降。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 22, true),
  ('ai-regularization', 'ai-research', 'regularization', '正则化', 'n.', 'Techniques used to prevent a model from overfitting by penalizing complexity.', 'Adding regularization brought the validation accuracy much closer to the training accuracy.', '加入正则化后，验证集准确率与训练集准确率之间的差距明显缩小了。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 23, true),
  ('ai-bias-variance-tradeoff', 'ai-research', 'bias-variance tradeoff', '偏差-方差权衡', 'n.', 'The balance between a model being too simple (high bias) and too complex (high variance).', 'Understanding the bias-variance tradeoff helped us pick a model that generalized well.', '理解偏差-方差权衡帮助我们选择了一个泛化能力更好的模型。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 24, true),
  ('ai-underfitting', 'ai-research', 'underfitting', '欠拟合', 'n.', 'A situation where a model is too simple to capture the underlying pattern in the data.', 'Underfitting was obvious once both training and validation accuracy stayed low.', '一旦发现训练集和验证集的准确率都很低，欠拟合的问题就很明显了。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 25, true),
  ('ai-cross-validation', 'ai-research', 'cross-validation', '交叉验证', 'n.', 'A technique for evaluating a model by training and testing it on different data splits.', 'Five-fold cross-validation gave a more reliable estimate of the model''s true performance.', '五折交叉验证给出了对模型真实性能更可靠的估计。', ARRAY['machine-learning', 'evaluation']::text[], null, null, 26, true),
  ('ai-ensemble-learning', 'ai-research', 'ensemble learning', '集成学习', 'n.', 'A technique that combines multiple models to produce better predictions than any single one.', 'Ensemble learning combined three different models to boost overall accuracy.', '集成学习结合了三个不同的模型，提升了整体准确率。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 27, true),
  ('ai-decision-tree', 'ai-research', 'decision tree', '决策树', 'n.', 'A model that makes predictions by following a tree of if-then rules.', 'The decision tree was easy to explain to stakeholders who weren''t technical.', '决策树很容易向不懂技术的干系人解释清楚。', ARRAY['machine-learning', 'model']::text[], null, null, 28, true),
  ('ai-random-forest', 'ai-research', 'random forest', '随机森林', 'n.', 'An ensemble method that combines many decision trees to improve prediction accuracy.', 'The random forest outperformed a single decision tree on almost every metric.', '随机森林在几乎每一项指标上都优于单一决策树。', ARRAY['machine-learning', 'model']::text[], null, null, 29, true),
  ('ai-support-vector-machine', 'ai-research', 'support vector machine', '支持向量机', 'n.', 'A model that finds the optimal boundary separating classes of data.', 'The support vector machine worked well on the small, high-dimensional dataset.', '支持向量机在这个小规模、高维度的数据集上表现良好。', ARRAY['machine-learning', 'model']::text[], null, null, 30, true),
  ('ai-k-nearest-neighbors', 'ai-research', 'k-nearest neighbors', 'K 近邻算法', 'n.', 'A model that classifies a data point based on the labels of its closest neighbors.', 'K-nearest neighbors was simple to implement but slow on the full-sized dataset.', 'K 近邻算法实现起来很简单，但在完整数据集上运行较慢。', ARRAY['machine-learning', 'model']::text[], null, null, 31, true),
  ('ai-clustering', 'ai-research', 'clustering', '聚类', 'n.', 'The task of grouping data points so that similar points end up in the same group.', 'Clustering revealed three distinct customer behavior patterns we hadn''t noticed before.', '聚类揭示出了三种我们此前未曾注意到的客户行为模式。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 32, true),
  ('ai-dimensionality-reduction', 'ai-research', 'dimensionality reduction', '降维', 'n.', 'Techniques for reducing the number of input variables while preserving important information.', 'Dimensionality reduction made the dataset small enough to visualize in two dimensions.', '降维让数据集变得足够小，可以在二维平面上进行可视化。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 33, true),
  ('ai-principal-component-analysis', 'ai-research', 'principal component analysis', '主成分分析', 'n.', 'A dimensionality reduction technique that projects data onto its directions of greatest variance.', 'Principal component analysis reduced two hundred features down to just ten.', '主成分分析把两百个特征压缩到了仅十个。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 34, true),
  ('ai-classification', 'ai-research', 'classification', '分类', 'n.', 'A task where a model predicts which category a given input belongs to.', 'This was a binary classification problem: either the email was spam or it wasn''t.', '这是一个二分类问题：邮件要么是垃圾邮件，要么不是。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 35, true),
  ('ai-regression', 'ai-research', 'regression', '回归', 'n.', 'A task where a model predicts a continuous numeric value.', 'We framed house price prediction as a regression problem rather than classification.', '我们把房价预测定义为一个回归问题，而不是分类问题。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 36, true),
  ('ai-confusion-matrix', 'ai-research', 'confusion matrix', '混淆矩阵', 'n.', 'A table showing the counts of correct and incorrect predictions across each class.', 'The confusion matrix revealed the model was mixing up two visually similar classes.', '混淆矩阵显示模型经常把两个外观相似的类别搞混。', ARRAY['machine-learning', 'evaluation']::text[], null, null, 37, true),
  ('ai-feature-selection', 'ai-research', 'feature selection', '特征选择', 'n.', 'The process of choosing the most relevant features to use in a model.', 'Feature selection dropped twelve columns that added noise without improving accuracy.', '特征选择去掉了十二个只增加噪声却无助于提升准确率的字段。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 38, true),
  ('ai-model-generalization', 'ai-research', 'model generalization', '模型泛化能力', 'n.', 'A model''s ability to perform well on new, previously unseen data.', 'Strong model generalization meant performance barely dropped on the test set.', '出色的模型泛化能力意味着在测试集上的表现几乎没有下降。', ARRAY['machine-learning', 'evaluation']::text[], null, null, 39, true),
  ('ai-weight-initialization', 'ai-research', 'weight initialization', '权重初始化', 'n.', 'The method used to set a neural network''s initial parameter values before training.', 'Poor weight initialization made the network fail to learn anything in the first few epochs.', '不恰当的权重初始化导致网络在最初几轮训练中什么都学不到。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 40, true),
  ('ai-activation-function', 'ai-research', 'activation function', '激活函数', 'n.', 'A function applied to a neuron''s output that introduces non-linearity into a network.', 'Switching the activation function from sigmoid to ReLU sped up training considerably.', '把激活函数从 sigmoid 换成 ReLU 后，训练速度明显加快了。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 41, true),
  ('ai-epoch', 'ai-research', 'epoch', '训练轮次', 'n.', 'One complete pass through the entire training dataset during training.', 'The model stopped improving noticeably after about twenty epochs.', '训练大约二十轮之后，模型的提升就不再明显了。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 42, true),
  ('ai-batch-size', 'ai-research', 'batch size', '批大小', 'n.', 'The number of training examples processed together in one step of model training.', 'A larger batch size sped up training but required more GPU memory.', '更大的批大小加快了训练速度，但也需要更多的 GPU 显存。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 43, true),
  ('ai-mini-batch', 'ai-research', 'mini-batch', '小批量', 'n.', 'A small subset of the training data used for a single gradient update step.', 'Training on mini-batches was far more memory-efficient than using the full dataset at once.', '使用小批量进行训练，在内存效率上远高于一次性使用整个数据集。', ARRAY['machine-learning', 'fundamentals']::text[], null, null, 44, true),
  ('ai-deep-neural-network', 'ai-research', 'deep neural network', '深度神经网络', 'n.', 'A neural network with many layers between the input and output.', 'The deep neural network had over fifty layers, far more than early models used.', '这个深度神经网络有超过五十层，比早期模型的层数多得多。', ARRAY['deep-learning', 'model']::text[], null, null, 45, true),
  ('ai-convolutional-neural-network', 'ai-research', 'convolutional neural network', '卷积神经网络', 'n.', 'A neural network architecture especially effective for processing image data.', 'A convolutional neural network powered the app''s photo classification feature.', '一个卷积神经网络驱动了该应用的照片分类功能。', ARRAY['deep-learning', 'model']::text[], null, null, 46, true),
  ('ai-recurrent-neural-network', 'ai-research', 'recurrent neural network', '循环神经网络', 'n.', 'A neural network architecture designed to process sequential data by maintaining a hidden state.', 'The recurrent neural network struggled with very long sequences compared to newer architectures.', '与更新的架构相比，这个循环神经网络在处理超长序列时表现较差。', ARRAY['deep-learning', 'model']::text[], null, null, 47, true),
  ('ai-long-short-term-memory', 'ai-research', 'long short-term memory', '长短期记忆网络', 'n.', 'A type of recurrent neural network designed to better capture long-range dependencies.', 'Long short-term memory networks were the standard choice for sequence tasks before transformers.', '在 Transformer 出现之前，长短期记忆网络是序列任务的标准选择。', ARRAY['deep-learning', 'model']::text[], null, null, 48, true),
  ('ai-multilayer-perceptron', 'ai-research', 'multilayer perceptron', '多层感知机', 'n.', 'A basic type of feedforward neural network with one or more hidden layers.', 'A simple multilayer perceptron was enough to solve this small classification task.', '一个简单的多层感知机就足以解决这个小型分类任务。', ARRAY['deep-learning', 'model']::text[], null, null, 49, true),
  ('ai-dropout', 'ai-research', 'dropout', '随机失活', 'n.', 'A regularization technique that randomly disables neurons during training to reduce overfitting.', 'Adding dropout at a rate of 0.3 reduced overfitting without hurting accuracy much.', '加入丢弃率为 0.3 的随机失活后，过拟合减少了，而准确率几乎没有受到影响。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 50, true),
  ('ai-batch-normalization', 'ai-research', 'batch normalization', '批归一化', 'n.', 'A technique that normalizes layer inputs to stabilize and speed up training.', 'Batch normalization let us use a much higher learning rate without the training diverging.', '批归一化让我们能够使用更高的学习率，同时训练也不会发散。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 51, true),
  ('ai-vanishing-gradient', 'ai-research', 'vanishing gradient', '梯度消失', 'n.', 'A problem where gradients become too small to effectively update earlier layers during training.', 'The vanishing gradient problem made the first few layers of the deep network barely learn anything.', '梯度消失问题让这个深度网络的前几层几乎学不到任何东西。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 52, true),
  ('ai-exploding-gradient', 'ai-research', 'exploding gradient', '梯度爆炸', 'n.', 'A problem where gradients grow uncontrollably large, destabilizing training.', 'Gradient clipping was added specifically to prevent exploding gradient during training.', '专门加入梯度裁剪就是为了防止训练过程中出现梯度爆炸。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 53, true),
  ('ai-residual-connection', 'ai-research', 'residual connection', '残差连接', 'n.', 'A shortcut connection that adds a layer''s input directly to its output to ease training of deep networks.', 'Residual connections made it possible to train networks with over a hundred layers.', '残差连接让训练超过一百层的网络成为了可能。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 54, true),
  ('ai-attention-mechanism', 'ai-research', 'attention mechanism', '注意力机制', 'n.', 'A technique that lets a model focus on the most relevant parts of its input.', 'The attention mechanism let the model focus on the relevant words when translating a long sentence.', '注意力机制让模型在翻译长句子时能够聚焦于相关的词语。', ARRAY['deep-learning', 'model']::text[], null, null, 55, true),
  ('ai-self-attention', 'ai-research', 'self-attention', '自注意力', 'n.', 'An attention mechanism that relates different positions within a single sequence to each other.', 'Self-attention let every word in the sentence directly attend to every other word.', '自注意力让句子中的每个词都能直接关注到其他所有词。', ARRAY['deep-learning', 'model']::text[], null, null, 56, true),
  ('ai-autoencoder', 'ai-research', 'autoencoder', '自编码器', 'n.', 'A neural network trained to compress data and then reconstruct it as accurately as possible.', 'The autoencoder learned to compress each image into a compact representation.', '这个自编码器学会了把每张图像压缩成一个紧凑的表示。', ARRAY['deep-learning', 'model']::text[], null, null, 57, true),
  ('ai-generative-adversarial-network', 'ai-research', 'generative adversarial network', '生成对抗网络', 'n.', 'A model architecture where a generator and a discriminator compete to improve each other.', 'The generative adversarial network produced remarkably realistic synthetic faces.', '这个生成对抗网络生成的合成人脸相当逼真。', ARRAY['deep-learning', 'model']::text[], null, null, 58, true),
  ('ai-diffusion-model', 'ai-research', 'diffusion model', '扩散模型', 'n.', 'A generative model that learns to produce data by reversing a gradual noising process.', 'The diffusion model generated a high-quality image from pure random noise in fifty steps.', '这个扩散模型仅用五十步就从纯随机噪声生成了一张高质量图像。', ARRAY['deep-learning', 'model']::text[], null, null, 59, true),
  ('ai-latent-space', 'ai-research', 'latent space', '潜在空间', 'n.', 'A compressed, learned representation of data where similar items are located close together.', 'Moving smoothly through the latent space produced a smooth transition between two generated images.', '在潜在空间中平滑移动，产生了两张生成图像之间的平滑过渡效果。', ARRAY['deep-learning', 'model']::text[], null, null, 60, true),
  ('ai-encoder', 'ai-research', 'encoder', '编码器', 'n.', 'A network component that transforms raw input into a compressed internal representation.', 'The encoder compressed the input sentence into a single fixed-length vector.', '编码器把输入句子压缩成了一个固定长度的向量。', ARRAY['deep-learning', 'model']::text[], null, null, 61, true),
  ('ai-decoder', 'ai-research', 'decoder', '解码器', 'n.', 'A network component that reconstructs or generates output from an internal representation.', 'The decoder generated the translated sentence one word at a time.', '解码器逐词生成了翻译后的句子。', ARRAY['deep-learning', 'model']::text[], null, null, 62, true),
  ('ai-skip-connection', 'ai-research', 'skip connection', '跳跃连接', 'n.', 'A connection that bypasses one or more layers, feeding information directly to a later layer.', 'The skip connection preserved fine details that would otherwise be lost in deeper layers.', '跳跃连接保留了那些原本会在更深的层中丢失的细节信息。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 63, true),
  ('ai-layer-normalization', 'ai-research', 'layer normalization', '层归一化', 'n.', 'A normalization technique applied across the features of a single training example.', 'Layer normalization is used inside transformers instead of batch normalization.', 'Transformer 内部使用的是层归一化，而不是批归一化。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 64, true),
  ('ai-pooling-layer', 'ai-research', 'pooling layer', '池化层', 'n.', 'A layer that reduces the spatial size of feature maps while retaining important information.', 'The pooling layer cut the image resolution in half after each convolutional block.', '池化层在每个卷积模块之后都会把图像分辨率减半。', ARRAY['deep-learning', 'model']::text[], null, null, 65, true),
  ('ai-feature-map', 'ai-research', 'feature map', '特征图', 'n.', 'The output of a convolutional layer, representing detected patterns at each spatial location.', 'Visualizing the feature map showed the network had learned to detect edges early on.', '可视化特征图显示，网络在早期就已经学会了检测边缘。', ARRAY['deep-learning', 'model']::text[], null, null, 66, true),
  ('ai-weight-sharing', 'ai-research', 'weight sharing', '权重共享', 'n.', 'Using the same set of parameters across different parts of a network to reduce parameter count.', 'Weight sharing across the convolutional filters kept the model small enough to run on mobile.', '卷积滤波器之间的权重共享让模型足够小，可以在手机上运行。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 67, true),
  ('ai-model-architecture', 'ai-research', 'model architecture', '模型架构', 'n.', 'The overall structure and design of layers and connections that make up a model.', 'We tried three different model architectures before settling on the final design.', '我们尝试了三种不同的模型架构，才最终确定了最后的设计方案。', ARRAY['deep-learning', 'model']::text[], null, null, 68, true),
  ('ai-gradient-clipping', 'ai-research', 'gradient clipping', '梯度裁剪', 'n.', 'A technique that caps gradient values to prevent them from becoming too large during training.', 'Gradient clipping kept training stable even with a relatively high learning rate.', '即使学习率相对较高，梯度裁剪也让训练保持了稳定。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 69, true),
  ('ai-optimizer', 'ai-research', 'optimizer', '优化器', 'n.', 'The algorithm responsible for updating model weights based on computed gradients.', 'Switching optimizers changed how quickly the model converged during training.', '更换优化器改变了模型在训练中收敛的速度。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 70, true),
  ('ai-adam-optimizer', 'ai-research', 'Adam optimizer', 'Adam 优化器', 'n.', 'A popular optimization algorithm that adapts the learning rate for each parameter individually.', 'The Adam optimizer converged faster than plain stochastic gradient descent on this task.', '在这个任务上，Adam 优化器的收敛速度比普通的随机梯度下降更快。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 71, true),
  ('ai-learning-rate-schedule', 'ai-research', 'learning rate schedule', '学习率调度策略', 'n.', 'A plan for how the learning rate changes over the course of training.', 'A cosine learning rate schedule gradually lowered the rate as training progressed.', '余弦学习率调度策略随着训练的推进逐渐降低了学习率。', ARRAY['deep-learning', 'fundamentals']::text[], null, null, 72, true),
  ('ai-model-checkpoint', 'ai-research', 'model checkpoint', '模型检查点', 'n.', 'A saved snapshot of a model''s parameters at a specific point during training.', 'We restored the best model checkpoint after the final few epochs made things worse.', '由于最后几轮训练反而让效果变差，我们恢复到了最优的模型检查点。', ARRAY['deep-learning', 'training']::text[], null, null, 73, true),
  ('ai-transfer-learning', 'ai-research', 'transfer learning', '迁移学习', 'n.', 'Reusing a model trained on one task as the starting point for a related task.', 'Transfer learning from a large pretrained model saved us weeks of training time.', '从一个大型预训练模型进行迁移学习，为我们节省了数周的训练时间。', ARRAY['deep-learning', 'training']::text[], null, null, 74, true),
  ('ai-pretrained-model', 'ai-research', 'pretrained model', '预训练模型', 'n.', 'A model that has already been trained on a large dataset before being adapted for a new task.', 'We started from a pretrained model instead of training from scratch.', '我们从一个预训练模型开始，而不是从零开始训练。', ARRAY['deep-learning', 'model']::text[], null, null, 75, true),
  ('ai-sparse-model', 'ai-research', 'sparse model', '稀疏模型', 'n.', 'A model where many parameters are zero or inactive, reducing computation and memory needs.', 'The sparse model activated only a fraction of its parameters for any given input.', '这个稀疏模型对于任意给定输入，只会激活其参数中的一小部分。', ARRAY['deep-learning', 'model']::text[], null, null, 76, true),
  ('ai-knowledge-distillation', 'ai-research', 'knowledge distillation', '知识蒸馏', 'n.', 'A technique where a smaller student model learns to mimic a larger teacher model.', 'Knowledge distillation compressed the large model into one a fifth of its size.', '知识蒸馏把大模型压缩成了体积仅为其五分之一的小模型。', ARRAY['deep-learning', 'training']::text[], null, null, 77, true),
  ('ai-mixture-of-experts', 'ai-research', 'mixture of experts', '混合专家模型', 'n.', 'An architecture that routes each input to a subset of specialized sub-networks called experts.', 'The mixture of experts model activated only two experts out of sixty-four for each token.', '这个混合专家模型对每个 token 只会激活六十四个专家中的两个。', ARRAY['deep-learning', 'model']::text[], null, null, 78, true),
  ('ai-neural-architecture-search', 'ai-research', 'neural architecture search', '神经架构搜索', 'n.', 'An automated process for discovering high-performing neural network architectures.', 'Neural architecture search found a model design that outperformed our hand-crafted one.', '神经架构搜索找到了一种性能超越我们手工设计模型的架构方案。', ARRAY['deep-learning', 'model']::text[], null, null, 79, true),
  ('ai-large-language-model', 'ai-research', 'large language model', '大语言模型', 'n.', 'A neural network trained on massive text data to understand and generate human language.', 'The large language model could answer questions on almost any topic we tried.', '这个大语言模型几乎能回答我们尝试的任何主题的问题。', ARRAY['llm', 'model']::text[], null, null, 80, true),
  ('ai-tokenization', 'ai-research', 'tokenization', '分词（词元化）', 'n.', 'The process of splitting text into smaller units, called tokens, for a model to process.', 'Tokenization split the sentence into subword pieces rather than whole words.', '分词把这句话拆分成了子词单元，而不是完整的单词。', ARRAY['llm', 'nlp']::text[], null, null, 81, true),
  ('ai-token', 'ai-research', 'token', '词元', 'n.', 'A basic unit of text, such as a word or subword, that a language model processes.', 'The prompt used about fifty tokens, well within the model''s limit.', '这段提示词大约用了五十个词元，完全在模型的限制范围之内。', ARRAY['llm', 'nlp']::text[], null, null, 82, true),
  ('ai-context-window', 'ai-research', 'context window', '上下文窗口', 'n.', 'The maximum amount of text a model can consider at once when generating a response.', 'The document was too long to fit inside the model''s context window.', '这份文档太长了，无法完整放入模型的上下文窗口。', ARRAY['llm', 'model']::text[], null, null, 83, true),
  ('ai-prompt', 'ai-research', 'prompt', '提示词', 'n.', 'The input text given to a language model to guide its response.', 'A more detailed prompt produced a much more useful answer.', '更详细的提示词得到了更有用的回答。', ARRAY['llm', 'fundamentals']::text[], null, null, 84, true),
  ('ai-prompt-engineering', 'ai-research', 'prompt engineering', '提示工程', 'n.', 'The practice of designing prompts to get better, more reliable outputs from a language model.', 'Prompt engineering turned a vague, unhelpful answer into a precise one.', '提示工程把一个模糊、没有帮助的回答变成了一个精准的答案。', ARRAY['llm', 'fundamentals']::text[], null, null, 85, true),
  ('ai-system-prompt', 'ai-research', 'system prompt', '系统提示词', 'n.', 'An instruction given to a language model that sets its behavior before the user''s input.', 'The system prompt told the model to always respond in a formal tone.', '系统提示词要求模型始终以正式的语气进行回应。', ARRAY['llm', 'fundamentals']::text[], null, null, 86, true),
  ('ai-few-shot-learning', 'ai-research', 'few-shot learning', '少样本学习', 'n.', 'Providing a model with a small number of examples within the prompt to guide its output.', 'Few-shot learning with three examples was enough to get the formatting right.', '在提示词中给出三个示例的少样本学习，就足以让格式变得正确。', ARRAY['llm', 'fundamentals']::text[], null, null, 87, true),
  ('ai-zero-shot-learning', 'ai-research', 'zero-shot learning', '零样本学习', 'n.', 'Asking a model to perform a task without providing any examples in the prompt.', 'Zero-shot learning worked surprisingly well for this common classification task.', '对于这个常见的分类任务，零样本学习的效果出乎意料地好。', ARRAY['llm', 'fundamentals']::text[], null, null, 88, true),
  ('ai-in-context-learning', 'ai-research', 'in-context learning', '上下文学习', 'n.', 'A model''s ability to learn a task from examples given directly in the prompt, without retraining.', 'In-context learning let the model pick up a new format just from the examples shown.', '上下文学习让模型仅通过给出的示例就学会了一种新的格式。', ARRAY['llm', 'fundamentals']::text[], null, null, 89, true),
  ('ai-chain-of-thought', 'ai-research', 'chain of thought', '思维链', 'n.', 'A prompting technique that asks a model to reason step by step before giving a final answer.', 'Chain of thought prompting made the model much more accurate on multi-step math problems.', '思维链提示让模型在多步数学问题上的准确率大幅提升。', ARRAY['llm', 'fundamentals']::text[], null, null, 90, true),
  ('ai-temperature', 'ai-research', 'temperature', '温度参数', 'n.', 'A sampling parameter that controls how random or deterministic a model''s output is.', 'Lowering the temperature made the model''s answers more consistent across runs.', '降低温度参数让模型在多次运行中的回答更加一致。', ARRAY['llm', 'fundamentals']::text[], null, null, 91, true),
  ('ai-top-p-sampling', 'ai-research', 'top-p sampling', 'Top-p 采样', 'n.', 'A sampling method that selects from the smallest set of tokens whose combined probability exceeds p.', 'Top-p sampling produced more natural text than always picking the single most likely token.', 'Top-p 采样生成的文本比总是选择概率最高的那个词元更自然。', ARRAY['llm', 'fundamentals']::text[], null, null, 92, true),
  ('ai-top-k-sampling', 'ai-research', 'top-k sampling', 'Top-k 采样', 'n.', 'A sampling method that restricts token selection to the k most likely candidates.', 'Top-k sampling with a small k value made the output more focused but less creative.', '较小 k 值的 Top-k 采样让输出更聚焦，但创造性有所下降。', ARRAY['llm', 'fundamentals']::text[], null, null, 93, true),
  ('ai-beam-search', 'ai-research', 'beam search', '束搜索', 'n.', 'A decoding strategy that keeps track of multiple candidate sequences to find a high-probability output.', 'Beam search produced a more coherent translation than greedy decoding did.', '束搜索生成的翻译比贪婪解码更连贯。', ARRAY['llm', 'fundamentals']::text[], null, null, 94, true),
  ('ai-greedy-decoding', 'ai-research', 'greedy decoding', '贪婪解码', 'n.', 'A decoding strategy that always picks the single most likely next token.', 'Greedy decoding was fast but sometimes got stuck in repetitive loops.', '贪婪解码速度很快，但有时会陷入重复循环。', ARRAY['llm', 'fundamentals']::text[], null, null, 95, true),
  ('ai-hallucination', 'ai-research', 'hallucination', '幻觉（AI 生成虚假内容）', 'n.', 'When a model generates confident but factually incorrect or fabricated information.', 'The model''s hallucination invented a citation that didn''t actually exist.', '模型的幻觉编造出了一篇实际上并不存在的引用文献。', ARRAY['llm', 'safety']::text[], null, null, 96, true),
  ('ai-instruction-tuning', 'ai-research', 'instruction tuning', '指令微调', 'n.', 'Fine-tuning a model on examples of instructions and desired responses to improve its helpfulness.', 'Instruction tuning made the model far better at following explicit user requests.', '指令微调让模型在遵循用户明确请求方面表现好了很多。', ARRAY['llm', 'training']::text[], null, null, 97, true),
  ('ai-reinforcement-learning-from-human-feedback', 'ai-research', 'reinforcement learning from human feedback', '基于人类反馈的强化学习', 'n.', 'A training technique that uses human preference data to further align a model''s behavior.', 'Reinforcement learning from human feedback made the assistant''s tone noticeably more helpful.', '基于人类反馈的强化学习让这个助手的语气明显变得更有帮助了。', ARRAY['llm', 'training']::text[], null, null, 98, true),
  ('ai-reward-model', 'ai-research', 'reward model', '奖励模型', 'n.', 'A model trained to score outputs based on how well they match human preferences.', 'The reward model was trained on thousands of human comparisons between two responses.', '这个奖励模型是基于数千次人类对两个回答进行比较的数据训练出来的。', ARRAY['llm', 'training']::text[], null, null, 99, true),
  ('ai-alignment', 'ai-research', 'alignment', '对齐', 'n.', 'Making a model''s behavior match human intentions and values.', 'Alignment work focused on making the model refuse harmful requests consistently.', '对齐工作的重点是让模型能够始终如一地拒绝有害请求。', ARRAY['llm', 'safety']::text[], null, null, 100, true),
  ('ai-constitutional-ai', 'ai-research', 'constitutional AI', '宪法式 AI', 'n.', 'A training approach that uses a set of written principles to guide a model''s self-critique and revision.', 'Constitutional AI let the model critique and revise its own draft answers automatically.', '宪法式 AI 让模型能够自动地对自己的初稿答案进行批判和修正。', ARRAY['llm', 'safety']::text[], null, null, 101, true),
  ('ai-context-length', 'ai-research', 'context length', '上下文长度', 'n.', 'The number of tokens a model can process as input at one time.', 'Doubling the context length let the model read the entire report in one pass.', '把上下文长度翻倍后，模型可以一次性读完整份报告。', ARRAY['llm', 'model']::text[], null, null, 102, true),
  ('ai-autoregressive-model', 'ai-research', 'autoregressive model', '自回归模型', 'n.', 'A model that generates output one token at a time, each based on the tokens before it.', 'As an autoregressive model, it generated the response word by word from left to right.', '作为一个自回归模型，它从左到右逐词生成回答。', ARRAY['llm', 'model']::text[], null, null, 103, true),
  ('ai-next-token-prediction', 'ai-research', 'next token prediction', '下一词元预测', 'n.', 'The core training objective where a model learns to predict the next token in a sequence.', 'Next token prediction on massive text corpora is how most language models are pretrained.', '在海量文本语料上进行下一词元预测，是大多数语言模型预训练的方式。', ARRAY['llm', 'training']::text[], null, null, 104, true),
  ('ai-positional-encoding', 'ai-research', 'positional encoding', '位置编码', 'n.', 'A technique that gives a transformer information about the order of tokens in a sequence.', 'Positional encoding let the model tell the difference between "dog bites man" and "man bites dog."', '位置编码让模型能够区分"狗咬人"和"人咬狗"这两句话。', ARRAY['llm', 'model']::text[], null, null, 105, true),
  ('ai-multi-head-attention', 'ai-research', 'multi-head attention', '多头注意力', 'n.', 'An attention mechanism that runs several attention operations in parallel to capture different relationships.', 'Multi-head attention let the model track grammar and meaning at the same time.', '多头注意力让模型能够同时关注语法和语义。', ARRAY['llm', 'model']::text[], null, null, 106, true),
  ('ai-model-weights', 'ai-research', 'model weights', '模型权重', 'n.', 'The learned numerical parameters that define a trained model''s behavior.', 'Downloading the model weights took over an hour because the file was so large.', '由于文件体积巨大，下载模型权重花了一个多小时。', ARRAY['llm', 'model']::text[], null, null, 107, true),
  ('ai-parameter-count', 'ai-research', 'parameter count', '参数量', 'n.', 'The total number of learnable weights in a model, often used as a rough measure of its size.', 'The parameter count jumped from one billion to seventy billion in the newer version.', '在新版本中，参数量从十亿跃升到了七百亿。', ARRAY['llm', 'model']::text[], null, null, 108, true),
  ('ai-open-weight-model', 'ai-research', 'open-weight model', '开放权重模型', 'n.', 'A model whose trained parameters are publicly released for others to download and run.', 'We fine-tuned an open-weight model instead of relying on a closed API.', '我们对一个开放权重模型进行了微调，而不是依赖一个封闭的 API。', ARRAY['llm', 'model']::text[], null, null, 109, true),
  ('ai-model-card', 'ai-research', 'model card', '模型卡片', 'n.', 'A document that describes a model''s intended use, limitations, and training details.', 'The model card listed the languages the model had been evaluated on.', '模型卡片列出了该模型经过评估的语言种类。', ARRAY['llm', 'governance']::text[], null, null, 110, true),
  ('ai-jailbreak', 'ai-research', 'jailbreak', '越狱（绕过模型限制）', 'n.', 'An attempt to bypass a model''s safety restrictions through crafted prompts.', 'The security team tested for jailbreak attempts before the assistant was released publicly.', '安全团队在助手正式公开发布之前测试了各种越狱尝试。', ARRAY['llm', 'safety']::text[], null, null, 111, true),
  ('ai-prompt-injection', 'ai-research', 'prompt injection', '提示词注入', 'n.', 'An attack that embeds malicious instructions within input text to manipulate a model''s behavior.', 'Prompt injection hidden in a webpage tricked the agent into leaking data.', '隐藏在网页中的提示词注入诱使智能体泄露了数据。', ARRAY['llm', 'safety']::text[], null, null, 112, true),
  ('ai-system-message', 'ai-research', 'system message', '系统消息', 'n.', 'A message that sets context or instructions for a model before the conversation begins.', 'The system message specified the assistant''s name and area of expertise.', '系统消息指定了这个助手的名称和专业领域。', ARRAY['llm', 'fundamentals']::text[], null, null, 113, true),
  ('ai-completion', 'ai-research', 'completion', '补全（模型生成结果）', 'n.', 'The text a language model generates in response to a given prompt.', 'The completion matched the requested format almost perfectly.', '这个补全结果几乎完美地符合了要求的格式。', ARRAY['llm', 'fundamentals']::text[], null, null, 114, true),
  ('ai-natural-language-understanding', 'ai-research', 'natural language understanding', '自然语言理解', 'n.', 'The subfield of NLP focused on extracting meaning and intent from human language.', 'Natural language understanding let the system correctly interpret ambiguous customer questions.', '自然语言理解让系统能够正确理解客户提出的模糊问题。', ARRAY['nlp', 'fundamentals']::text[], null, null, 115, true),
  ('ai-natural-language-generation', 'ai-research', 'natural language generation', '自然语言生成', 'n.', 'The subfield of NLP focused on producing human-readable text from structured data or models.', 'Natural language generation turned the raw sales numbers into a readable summary.', '自然语言生成把原始的销售数字转换成了一段可读的摘要。', ARRAY['nlp', 'fundamentals']::text[], null, null, 116, true),
  ('ai-named-entity-recognition', 'ai-research', 'named entity recognition', '命名实体识别', 'n.', 'The task of identifying and classifying names of people, places, or organizations in text.', 'Named entity recognition pulled every company name out of the earnings call transcript.', '命名实体识别从这份财报电话会议记录中提取出了所有公司名称。', ARRAY['nlp', 'fundamentals']::text[], null, null, 117, true),
  ('ai-part-of-speech-tagging', 'ai-research', 'part-of-speech tagging', '词性标注', 'n.', 'The task of labeling each word in a sentence with its grammatical role.', 'Part-of-speech tagging identified which words were verbs before the parser ran.', '词性标注在句法分析器运行之前先识别出了哪些词是动词。', ARRAY['nlp', 'fundamentals']::text[], null, null, 118, true),
  ('ai-sentiment-analysis', 'ai-research', 'sentiment analysis', '情感分析', 'n.', 'The task of determining the emotional tone expressed in a piece of text.', 'Sentiment analysis flagged a sharp rise in negative reviews after the price increase.', '情感分析发现涨价后负面评价明显增多。', ARRAY['nlp', 'fundamentals']::text[], null, null, 119, true),
  ('ai-text-classification', 'ai-research', 'text classification', '文本分类', 'n.', 'The task of assigning predefined categories to a piece of text.', 'Text classification automatically routed support tickets to the right department.', '文本分类自动把客服工单分派到了正确的部门。', ARRAY['nlp', 'fundamentals']::text[], null, null, 120, true),
  ('ai-text-summarization', 'ai-research', 'text summarization', '文本摘要', 'n.', 'The task of producing a shorter version of a text that preserves its key information.', 'Text summarization condensed the fifty-page report into a single readable page.', '文本摘要把这份五十页的报告浓缩成了一页可读的内容。', ARRAY['nlp', 'fundamentals']::text[], null, null, 121, true),
  ('ai-machine-translation', 'ai-research', 'machine translation', '机器翻译', 'n.', 'The task of automatically translating text from one language to another.', 'Machine translation quality has improved dramatically since neural models replaced older methods.', '自从神经网络模型取代了旧方法，机器翻译的质量有了显著提升。', ARRAY['nlp', 'fundamentals']::text[], null, null, 122, true),
  ('ai-question-answering', 'ai-research', 'question answering', '问答系统', 'n.', 'A task where a system provides direct answers to natural language questions.', 'The question answering system pulled the exact answer straight from the manual.', '这个问答系统直接从说明书中提取出了准确答案。', ARRAY['nlp', 'fundamentals']::text[], null, null, 123, true),
  ('ai-coreference-resolution', 'ai-research', 'coreference resolution', '指代消解', 'n.', 'The task of determining which words in a text refer to the same real-world entity.', 'Coreference resolution correctly linked "she" back to "the CEO" mentioned two sentences earlier.', '指代消解正确地把"她"和两句之前提到的"首席执行官"关联了起来。', ARRAY['nlp', 'fundamentals']::text[], null, null, 124, true),
  ('ai-dependency-parsing', 'ai-research', 'dependency parsing', '依存句法分析', 'n.', 'The task of analyzing the grammatical structure of a sentence to show relationships between words.', 'Dependency parsing showed that "quickly" modified the verb "ran," not the noun.', '依存句法分析显示"quickly"修饰的是动词"ran"，而不是名词。', ARRAY['nlp', 'fundamentals']::text[], null, null, 125, true),
  ('ai-word-embedding', 'ai-research', 'word embedding', '词嵌入', 'n.', 'A dense numerical vector representation of a word that captures aspects of its meaning.', 'The word embedding for "king" ended up mathematically close to the embedding for "queen."', '"king"的词嵌入在数学上与"queen"的词嵌入非常接近。', ARRAY['nlp', 'fundamentals']::text[], null, null, 126, true),
  ('ai-bag-of-words', 'ai-research', 'bag of words', '词袋模型', 'n.', 'A simple text representation that counts word occurrences while ignoring order and grammar.', 'A bag of words model was a fast baseline before we tried anything more sophisticated.', '在尝试更复杂的方法之前，词袋模型是一个快速的基线方案。', ARRAY['nlp', 'fundamentals']::text[], null, null, 127, true),
  ('ai-tf-idf', 'ai-research', 'TF-IDF', '词频-逆文档频率', 'n.', 'A statistic that measures how important a word is to a document within a larger collection.', 'TF-IDF down-weighted common words like "the" that appeared in nearly every document.', '词频-逆文档频率降低了像"the"这类几乎出现在每份文档中的常见词的权重。', ARRAY['nlp', 'fundamentals']::text[], null, null, 128, true),
  ('ai-n-gram', 'ai-research', 'n-gram', 'N 元语法', 'n.', 'A contiguous sequence of n words or tokens used to model local language patterns.', 'The n-gram model captured common two-word phrases but missed longer-range context.', '这个 N 元语法模型能捕捉常见的双词短语，但会遗漏更长距离的上下文关系。', ARRAY['nlp', 'fundamentals']::text[], null, null, 129, true),
  ('ai-stemming', 'ai-research', 'stemming', '词干提取', 'n.', 'Reducing words to their root form by stripping suffixes, often crudely.', 'Stemming reduced "running," "runs," and "runner" all down to "run."', '词干提取把"running"、"runs"和"runner"都简化成了"run"。', ARRAY['nlp', 'fundamentals']::text[], null, null, 130, true),
  ('ai-lemmatization', 'ai-research', 'lemmatization', '词形还原', 'n.', 'Reducing words to their dictionary base form using vocabulary and grammar rules.', 'Lemmatization correctly reduced "better" to "good," unlike simple stemming.', '与简单的词干提取不同，词形还原正确地把"better"还原成了"good"。', ARRAY['nlp', 'fundamentals']::text[], null, null, 131, true),
  ('ai-stop-words', 'ai-research', 'stop words', '停用词', 'n.', 'Common words like "the" or "is" that are often filtered out before text analysis.', 'Removing stop words shrank the vocabulary size by nearly half.', '去除停用词后，词表规模减少了近一半。', ARRAY['nlp', 'fundamentals']::text[], null, null, 132, true),
  ('ai-corpus', 'ai-research', 'corpus', '语料库', 'n.', 'A large, structured collection of text used for training or analyzing language models.', 'The corpus contained over ten million sentences scraped from public documents.', '这个语料库包含了从公开文档中抓取的超过一千万个句子。', ARRAY['nlp', 'data']::text[], null, null, 133, true),
  ('ai-language-model', 'ai-research', 'language model', '语言模型', 'n.', 'A model trained to predict or generate text based on patterns learned from language data.', 'An early language model could only predict the next word based on the previous two.', '早期的语言模型只能根据前两个词来预测下一个词。', ARRAY['nlp', 'model']::text[], null, null, 134, true),
  ('ai-semantic-similarity', 'ai-research', 'semantic similarity', '语义相似度', 'n.', 'A measure of how close two pieces of text are in meaning.', 'Semantic similarity matched the customer question to a support article even without shared keywords.', '即使没有相同的关键词，语义相似度也能把客户问题匹配到对应的帮助文档。', ARRAY['nlp', 'fundamentals']::text[], null, null, 135, true),
  ('ai-text-normalization', 'ai-research', 'text normalization', '文本规范化', 'n.', 'The process of converting text into a consistent, standard format before processing.', 'Text normalization lowercased and removed extra punctuation before tokenization.', '文本规范化在分词之前把文本转成了小写并去除了多余的标点符号。', ARRAY['nlp', 'fundamentals']::text[], null, null, 136, true),
  ('ai-entity-linking', 'ai-research', 'entity linking', '实体链接', 'n.', 'The task of connecting a mentioned entity in text to its corresponding record in a knowledge base.', 'Entity linking connected "Apple" in the article to the correct company, not the fruit.', '实体链接把文章中的"Apple"正确地关联到了对应的公司，而不是水果。', ARRAY['nlp', 'fundamentals']::text[], null, null, 137, true),
  ('ai-topic-modeling', 'ai-research', 'topic modeling', '主题建模', 'n.', 'A technique for discovering abstract topics that occur across a collection of documents.', 'Topic modeling revealed that customer complaints clustered around three recurring themes.', '主题建模揭示出客户投诉集中在三个反复出现的主题上。', ARRAY['nlp', 'fundamentals']::text[], null, null, 138, true),
  ('ai-word-sense-disambiguation', 'ai-research', 'word sense disambiguation', '词义消歧', 'n.', 'The task of determining which meaning of a word is intended given its context.', 'Word sense disambiguation figured out that "bank" referred to a riverbank, not a financial institution.', '词义消歧判断出"bank"在这里指的是河岸，而不是金融机构。', ARRAY['nlp', 'fundamentals']::text[], null, null, 139, true),
  ('ai-sequence-labeling', 'ai-research', 'sequence labeling', '序列标注', 'n.', 'The task of assigning a label to each element in a sequence, such as each word in a sentence.', 'Sequence labeling tagged each token in the resume as a skill, company, or date.', '序列标注给简历中的每个词元都打上了技能、公司或日期的标签。', ARRAY['nlp', 'fundamentals']::text[], null, null, 140, true),
  ('ai-text-to-speech', 'ai-research', 'text-to-speech', '文本转语音', 'n.', 'The technology that converts written text into spoken audio.', 'Text-to-speech read the article aloud in a natural-sounding voice.', '文本转语音以一种自然的声音朗读了这篇文章。', ARRAY['nlp', 'deployment']::text[], null, null, 141, true),
  ('ai-speech-to-text', 'ai-research', 'speech-to-text', '语音转文本', 'n.', 'The technology that converts spoken audio into written text.', 'Speech-to-text transcribed the entire hour-long meeting in real time.', '语音转文本实时转录了这场长达一小时的会议。', ARRAY['nlp', 'deployment']::text[], null, null, 142, true),
  ('ai-dialogue-system', 'ai-research', 'dialogue system', '对话系统', 'n.', 'A system designed to converse with users in natural language, such as a chatbot.', 'The dialogue system remembered context from earlier in the conversation.', '这个对话系统能够记住对话中较早部分的上下文。', ARRAY['nlp', 'model']::text[], null, null, 143, true),
  ('ai-intent-classification', 'ai-research', 'intent classification', '意图分类', 'n.', 'The task of identifying what a user is trying to achieve from their input text.', 'Intent classification routed the message to "cancel order" instead of "track order."', '意图分类把这条消息归类为"取消订单"，而不是"查询订单"。', ARRAY['nlp', 'fundamentals']::text[], null, null, 144, true),
  ('ai-slot-filling', 'ai-research', 'slot filling', '槽位填充', 'n.', 'The task of extracting specific pieces of structured information from a user''s natural language input.', 'Slot filling extracted the date, time, and party size from a single reservation request.', '槽位填充从一条预订请求中提取出了日期、时间和用餐人数。', ARRAY['nlp', 'fundamentals']::text[], null, null, 145, true),
  ('ai-multilingual-model', 'ai-research', 'multilingual model', '多语言模型', 'n.', 'A model trained to understand or generate text across multiple languages.', 'The multilingual model handled customer support in twelve languages with one deployment.', '这个多语言模型通过一次部署就能处理十二种语言的客户支持。', ARRAY['nlp', 'model']::text[], null, null, 146, true),
  ('ai-tokenizer-vocabulary', 'ai-research', 'tokenizer vocabulary', '分词器词表', 'n.', 'The fixed set of tokens a tokenizer can produce when splitting text.', 'The tokenizer vocabulary had thirty thousand entries covering common subwords across languages.', '这个分词器词表包含三万个条目，涵盖了多种语言的常见子词。', ARRAY['nlp', 'model']::text[], null, null, 147, true),
  ('ai-subword-tokenization', 'ai-research', 'subword tokenization', '子词分词', 'n.', 'Splitting words into smaller, reusable pieces to handle rare or unseen words.', 'Subword tokenization split the unfamiliar word into two recognizable pieces.', '子词分词把这个生僻词拆分成了两个可识别的部分。', ARRAY['nlp', 'fundamentals']::text[], null, null, 148, true),
  ('ai-syntactic-parsing', 'ai-research', 'syntactic parsing', '句法解析', 'n.', 'The process of analyzing the grammatical structure of a sentence.', 'Syntactic parsing built a tree showing how each phrase in the sentence related to the others.', '句法解析构建了一棵树，展示了句中每个短语之间的关系。', ARRAY['nlp', 'fundamentals']::text[], null, null, 149, true),
  ('ai-image-classification', 'ai-research', 'image classification', '图像分类', 'n.', 'The task of assigning a single label to an entire image based on its content.', 'Image classification correctly labeled ninety-eight percent of the test photos as cats or dogs.', '图像分类正确标注了 98% 的测试照片，判断出图中是猫还是狗。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 150, true),
  ('ai-object-detection', 'ai-research', 'object detection', '目标检测', 'n.', 'The task of locating and classifying multiple objects within an image.', 'Object detection drew a box around every car and pedestrian in the street scene.', '目标检测在这张街景图中的每辆车和每个行人周围都画出了框。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 151, true),
  ('ai-semantic-segmentation', 'ai-research', 'semantic segmentation', '语义分割', 'n.', 'The task of labeling every pixel in an image with the category of object it belongs to.', 'Semantic segmentation separated the road, sidewalk, and sky into distinct regions.', '语义分割把道路、人行道和天空分成了不同的区域。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 152, true),
  ('ai-instance-segmentation', 'ai-research', 'instance segmentation', '实例分割', 'n.', 'The task of detecting and outlining each individual object instance separately in an image.', 'Instance segmentation distinguished between three different people standing close together.', '实例分割区分出了三个站得很近的不同的人。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 153, true),
  ('ai-image-generation', 'ai-research', 'image generation', '图像生成', 'n.', 'The task of creating new images, often from a text description or random input.', 'Image generation produced a realistic photo from nothing but a short text prompt.', '图像生成仅凭一段简短的文字提示，就生成了一张逼真的照片。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 154, true),
  ('ai-optical-character-recognition', 'ai-research', 'optical character recognition', '光学字符识别', 'n.', 'The technology that converts images of text into machine-readable text.', 'Optical character recognition extracted the invoice number from a scanned PDF.', '光学字符识别从一份扫描版 PDF 中提取出了发票号码。', ARRAY['computer-vision', 'deployment']::text[], null, null, 155, true),
  ('ai-facial-recognition', 'ai-research', 'facial recognition', '人脸识别', 'n.', 'The technology that identifies or verifies a person based on their facial features.', 'Facial recognition unlocked the phone in under a second.', '人脸识别在不到一秒钟内就解锁了手机。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 156, true),
  ('ai-pose-estimation', 'ai-research', 'pose estimation', '姿态估计', 'n.', 'The task of predicting the position of a person''s body joints from an image or video.', 'Pose estimation tracked the athlete''s joint angles throughout the jump.', '姿态估计在整个跳跃过程中追踪了运动员的关节角度。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 157, true),
  ('ai-bounding-box', 'ai-research', 'bounding box', '边界框', 'n.', 'A rectangular box that marks the location of a detected object in an image.', 'Each bounding box was labeled with the object''s class and confidence score.', '每个边界框都标注了对象的类别和置信度分数。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 158, true),
  ('ai-anchor-box', 'ai-research', 'anchor box', '锚框', 'n.', 'A predefined reference box used by object detection models to predict object locations.', 'The model used nine anchor boxes of different sizes at every location in the image.', '该模型在图像的每个位置都使用了九种不同尺寸的锚框。', ARRAY['computer-vision', 'model']::text[], null, null, 159, true),
  ('ai-non-maximum-suppression', 'ai-research', 'non-maximum suppression', '非极大值抑制', 'n.', 'A technique that removes duplicate, overlapping detections and keeps only the best one.', 'Non-maximum suppression removed the five overlapping boxes drawn around the same car.', '非极大值抑制去除了围绕同一辆车画出的五个重叠框。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 160, true),
  ('ai-intersection-over-union', 'ai-research', 'intersection over union', '交并比', 'n.', 'A metric that measures the overlap between a predicted region and the ground truth region.', 'An intersection over union above 0.5 was required for a detection to count as correct.', '交并比需要超过 0.5，检测结果才算正确。', ARRAY['computer-vision', 'evaluation']::text[], null, null, 161, true),
  ('ai-feature-pyramid', 'ai-research', 'feature pyramid', '特征金字塔', 'n.', 'A multi-scale representation of an image used to detect objects of different sizes.', 'The feature pyramid helped the model detect both tiny and large objects in the same image.', '特征金字塔帮助模型在同一张图像中同时检测出微小和巨大的物体。', ARRAY['computer-vision', 'model']::text[], null, null, 162, true),
  ('ai-image-augmentation', 'ai-research', 'image augmentation', '图像增强', 'n.', 'Techniques that create modified copies of training images to improve model robustness.', 'Image augmentation randomly rotated and flipped photos to expand the training set.', '图像增强通过随机旋转和翻转照片来扩充训练集。', ARRAY['computer-vision', 'training']::text[], null, null, 163, true),
  ('ai-convolution-kernel', 'ai-research', 'convolution kernel', '卷积核', 'n.', 'A small matrix of weights slid across an image to detect specific visual patterns.', 'Each convolution kernel in the first layer learned to detect a different type of edge.', '第一层中的每个卷积核都学会了检测一种不同类型的边缘。', ARRAY['computer-vision', 'model']::text[], null, null, 164, true),
  ('ai-stride', 'ai-research', 'stride', '步幅', 'n.', 'The number of pixels a convolution kernel moves at each step across an image.', 'Increasing the stride reduced the output size and sped up computation.', '增大步幅缩小了输出尺寸，也加快了计算速度。', ARRAY['computer-vision', 'model']::text[], null, null, 165, true),
  ('ai-receptive-field', 'ai-research', 'receptive field', '感受野', 'n.', 'The region of the input image that influences a particular neuron''s output.', 'Deeper layers had a much larger receptive field, capturing more global context.', '更深的层拥有更大的感受野，能够捕捉到更多全局的上下文信息。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 166, true),
  ('ai-vision-transformer', 'ai-research', 'vision transformer', '视觉 Transformer', 'n.', 'A transformer-based architecture adapted to process images by treating patches as tokens.', 'The vision transformer split each image into sixteen-by-sixteen pixel patches.', '这个视觉 Transformer 把每张图像切分成了 16x16 像素的图像块。', ARRAY['computer-vision', 'model']::text[], null, null, 167, true),
  ('ai-image-captioning', 'ai-research', 'image captioning', '图像描述生成', 'n.', 'The task of automatically generating a text description of an image''s contents.', 'Image captioning described the photo as "a dog running on a beach at sunset."', '图像描述生成把这张照片描述为"一只狗在日落时分的海滩上奔跑"。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 168, true),
  ('ai-video-understanding', 'ai-research', 'video understanding', '视频理解', 'n.', 'The task of extracting meaning, actions, or events from video content.', 'Video understanding flagged the moment a package was left at the door.', '视频理解识别出了包裹被放在门口的那一刻。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 169, true),
  ('ai-optical-flow', 'ai-research', 'optical flow', '光流', 'n.', 'The pattern of apparent motion of objects between two consecutive video frames.', 'Optical flow estimated how fast and in which direction each car was moving.', '光流估算出了每辆车移动的速度和方向。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 170, true),
  ('ai-depth-estimation', 'ai-research', 'depth estimation', '深度估计', 'n.', 'The task of predicting the distance of objects in a scene from a single camera image.', 'Depth estimation let the robot judge how far away the obstacle was.', '深度估计让机器人能够判断障碍物的距离。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 171, true),
  ('ai-image-super-resolution', 'ai-research', 'image super-resolution', '图像超分辨率', 'n.', 'The task of reconstructing a high-resolution image from a lower-resolution input.', 'Image super-resolution restored fine detail in the old, blurry photograph.', '图像超分辨率技术在这张模糊的老照片中恢复出了精细的细节。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 172, true),
  ('ai-style-transfer', 'ai-research', 'style transfer', '风格迁移', 'n.', 'A technique that applies the visual style of one image to the content of another.', 'Style transfer turned the photograph into something that looked like a watercolor painting.', '风格迁移把这张照片变成了看起来像水彩画的效果。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 173, true),
  ('ai-anomaly-detection', 'ai-research', 'anomaly detection', '异常检测', 'n.', 'The task of identifying data points or images that deviate significantly from the norm.', 'Anomaly detection flagged a manufacturing defect the human inspector had missed.', '异常检测发现了一处人工检查员遗漏的制造缺陷。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 174, true),
  ('ai-scene-understanding', 'ai-research', 'scene understanding', '场景理解', 'n.', 'The task of interpreting the overall context and layout of a visual scene.', 'Scene understanding recognized the image as an office rather than just listing individual objects.', '场景理解把这张图像识别为一间办公室，而不只是罗列出其中的各个物体。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 175, true),
  ('ai-panoptic-segmentation', 'ai-research', 'panoptic segmentation', '全景分割', 'n.', 'A task that combines semantic and instance segmentation to label every pixel and object.', 'Panoptic segmentation labeled the sky as one region and each car as a separate instance.', '全景分割把天空标注为一个整体区域，同时把每辆车标注为单独的实例。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 176, true),
  ('ai-multi-object-tracking', 'ai-research', 'multi-object tracking', '多目标跟踪', 'n.', 'The task of following multiple objects across consecutive video frames over time.', 'Multi-object tracking kept a consistent ID on each player throughout the match.', '多目标跟踪在整场比赛中为每名球员保持了一致的编号。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 177, true),
  ('ai-keypoint-detection', 'ai-research', 'keypoint detection', '关键点检测', 'n.', 'The task of locating specific, predefined points of interest within an image, such as joints.', 'Keypoint detection identified the exact position of each finger joint in the hand.', '关键点检测精确定位出了手部每个指关节的位置。', ARRAY['computer-vision', 'fundamentals']::text[], null, null, 178, true),
  ('ai-image-embedding', 'ai-research', 'image embedding', '图像嵌入', 'n.', 'A dense numerical vector representation that captures the visual content of an image.', 'Similar-looking products ended up close together in the image embedding space.', '外观相似的商品在图像嵌入空间中会彼此靠得很近。', ARRAY['computer-vision', 'model']::text[], null, null, 179, true),
  ('ai-contrastive-learning', 'ai-research', 'contrastive learning', '对比学习', 'n.', 'A training approach that teaches a model to pull similar examples together and push dissimilar ones apart.', 'Contrastive learning taught the model that two crops of the same photo should have similar embeddings.', '对比学习让模型学会了同一张照片的两个裁剪片段应该拥有相似的嵌入表示。', ARRAY['computer-vision', 'training']::text[], null, null, 180, true),
  ('ai-self-supervised-pretraining', 'ai-research', 'self-supervised pretraining', '自监督预训练', 'n.', 'Pretraining a model on unlabeled data using a task the model can generate labels for itself.', 'Self-supervised pretraining on millions of unlabeled photos improved downstream accuracy.', '在数百万张未标注照片上进行的自监督预训练，提升了下游任务的准确率。', ARRAY['computer-vision', 'training']::text[], null, null, 181, true),
  ('ai-data-augmentation-pipeline', 'ai-research', 'data augmentation pipeline', '数据增强流水线', 'n.', 'A configured sequence of transformations applied automatically to training data.', 'The data augmentation pipeline applied random crops, flips, and color jitter to every image.', '数据增强流水线对每张图像都应用了随机裁剪、翻转和色彩抖动。', ARRAY['computer-vision', 'data']::text[], null, null, 182, true),
  ('ai-image-preprocessing', 'ai-research', 'image preprocessing', '图像预处理', 'n.', 'Steps taken to prepare raw images for input into a model, such as resizing or normalizing.', 'Image preprocessing resized every photo to the same fixed dimensions before training.', '图像预处理在训练之前把每张照片都调整成了相同的固定尺寸。', ARRAY['computer-vision', 'data']::text[], null, null, 183, true),
  ('ai-label-noise', 'ai-research', 'label noise', '标签噪声', 'n.', 'Errors or inaccuracies present in the labels of a training dataset.', 'Label noise from crowdsourced annotators lowered the model''s final accuracy.', '来自众包标注人员的标签噪声降低了模型最终的准确率。', ARRAY['computer-vision', 'data']::text[], null, null, 184, true),
  ('ai-supervised-fine-tuning', 'ai-research', 'supervised fine-tuning', '监督微调', 'n.', 'Fine-tuning a pretrained model on labeled examples for a specific task.', 'Supervised fine-tuning on customer support transcripts made the model far more useful for our use case.', '在客服对话记录上进行的监督微调，让模型对我们的场景更加有用。', ARRAY['training', 'llm']::text[], null, null, 185, true),
  ('ai-parameter-efficient-fine-tuning', 'ai-research', 'parameter-efficient fine-tuning', '参数高效微调', 'n.', 'Fine-tuning techniques that update only a small subset of a model''s parameters.', 'Parameter-efficient fine-tuning let us adapt the model using a fraction of the usual compute.', '参数高效微调让我们只用平常一小部分的算力就完成了模型适配。', ARRAY['training', 'llm']::text[], null, null, 186, true),
  ('ai-lora', 'ai-research', 'LoRA', 'LoRA（低秩适应）', 'n.', 'A parameter-efficient fine-tuning method that adds small trainable low-rank matrices to a model.', 'LoRA let us fine-tune the huge model on a single GPU instead of a whole cluster.', 'LoRA 让我们能在单张 GPU 上完成对这个巨大模型的微调，而不需要整个集群。', ARRAY['training', 'llm']::text[], null, null, 187, true),
  ('ai-quantization', 'ai-research', 'quantization', '量化', 'n.', 'Reducing the numerical precision of model weights to save memory and speed up inference.', 'Quantization shrank the model to a quarter of its original size with minimal accuracy loss.', '量化把模型压缩到了原来大小的四分之一，而准确率几乎没有下降。', ARRAY['training', 'deployment']::text[], null, null, 188, true),
  ('ai-model-compression', 'ai-research', 'model compression', '模型压缩', 'n.', 'Techniques used to reduce a model''s size while preserving as much performance as possible.', 'Model compression made it possible to run the assistant directly on a smartphone.', '模型压缩让这个助手能够直接在智能手机上运行。', ARRAY['training', 'deployment']::text[], null, null, 189, true),
  ('ai-pruning', 'ai-research', 'pruning', '剪枝', 'n.', 'Removing unnecessary weights or connections from a neural network to reduce its size.', 'Pruning removed forty percent of the weights without noticeably hurting accuracy.', '剪枝去除了 40% 的权重，而准确率没有明显下降。', ARRAY['training', 'deployment']::text[], null, null, 190, true),
  ('ai-curriculum-learning', 'ai-research', 'curriculum learning', '课程学习', 'n.', 'A training strategy that presents examples to a model in order of increasing difficulty.', 'Curriculum learning started with short sentences before gradually introducing longer, harder ones.', '课程学习从短句子开始，再逐步引入更长、更难的句子。', ARRAY['training', 'fundamentals']::text[], null, null, 191, true),
  ('ai-warm-up-steps', 'ai-research', 'warm-up steps', '预热步数', 'n.', 'An initial training period where the learning rate is gradually increased from a small value.', 'Adding warm-up steps prevented the loss from spiking at the very start of training.', '加入预热步数避免了损失值在训练最开始出现骤增。', ARRAY['training', 'fundamentals']::text[], null, null, 192, true),
  ('ai-gradient-accumulation', 'ai-research', 'gradient accumulation', '梯度累积', 'n.', 'A technique that simulates a larger batch size by accumulating gradients over several smaller batches.', 'Gradient accumulation let us train with an effective batch size larger than our GPU memory allowed.', '梯度累积让我们能够以超出 GPU 显存限制的有效批大小进行训练。', ARRAY['training', 'fundamentals']::text[], null, null, 193, true),
  ('ai-distributed-training', 'ai-research', 'distributed training', '分布式训练', 'n.', 'Training a model across multiple machines or devices simultaneously to speed up the process.', 'Distributed training across sixty-four GPUs cut the training time from weeks to days.', '在六十四张 GPU 上进行的分布式训练，把训练时间从几周缩短到了几天。', ARRAY['training', 'deployment']::text[], null, null, 194, true),
  ('ai-data-parallelism', 'ai-research', 'data parallelism', '数据并行', 'n.', 'A distributed training strategy that splits training data across multiple devices running the same model.', 'Data parallelism let each GPU process a different batch of the same dataset simultaneously.', '数据并行让每张 GPU 能同时处理同一数据集的不同批次。', ARRAY['training', 'deployment']::text[], null, null, 195, true),
  ('ai-model-parallelism', 'ai-research', 'model parallelism', '模型并行', 'n.', 'A distributed training strategy that splits a single model''s layers across multiple devices.', 'Model parallelism was necessary because the model was too large to fit on one GPU.', '由于模型太大，单张 GPU 无法容纳，因此需要使用模型并行。', ARRAY['training', 'deployment']::text[], null, null, 196, true),
  ('ai-mixed-precision-training', 'ai-research', 'mixed precision training', '混合精度训练', 'n.', 'Training that uses lower numerical precision for some calculations to speed up training and save memory.', 'Mixed precision training roughly doubled our training throughput.', '混合精度训练让我们的训练吞吐量大致提高了一倍。', ARRAY['training', 'fundamentals']::text[], null, null, 197, true),
  ('ai-checkpoint-resume', 'ai-research', 'checkpoint resume', '断点续训', 'n.', 'Restarting training from a saved checkpoint rather than from scratch.', 'Checkpoint resume let us continue training right where it stopped after the server crashed.', '断点续训让我们能在服务器崩溃后，从中断的地方继续训练。', ARRAY['training', 'fundamentals']::text[], null, null, 198, true),
  ('ai-early-stopping', 'ai-research', 'early stopping', '早停法', 'n.', 'Halting training once validation performance stops improving, to avoid overfitting.', 'Early stopping ended training after five epochs with no further improvement.', '早停法在连续五轮训练没有进一步提升后，就结束了训练。', ARRAY['training', 'fundamentals']::text[], null, null, 199, true),
  ('ai-training-loss-curve', 'ai-research', 'training loss curve', '训练损失曲线', 'n.', 'A plot of a model''s loss on the training set over the course of training.', 'The training loss curve showed a smooth, steady decline with no sudden spikes.', '训练损失曲线呈现出平稳、持续的下降，没有出现突然的波动。', ARRAY['training', 'metrics']::text[], null, null, 200, true),
  ('ai-validation-loss', 'ai-research', 'validation loss', '验证损失', 'n.', 'A measure of a model''s error on a held-out validation dataset during training.', 'Validation loss started increasing even as training loss kept dropping, a clear sign of overfitting.', '验证损失开始上升，而训练损失仍在下降，这是过拟合的明显信号。', ARRAY['training', 'metrics']::text[], null, null, 201, true),
  ('ai-hyperparameter-tuning', 'ai-research', 'hyperparameter tuning', '超参数调优', 'n.', 'The process of searching for the best combination of hyperparameters for a model.', 'Hyperparameter tuning improved accuracy by two full percentage points.', '超参数调优让准确率提高了整整两个百分点。', ARRAY['training', 'fundamentals']::text[], null, null, 202, true),
  ('ai-grid-search', 'ai-research', 'grid search', '网格搜索', 'n.', 'A hyperparameter tuning method that exhaustively tries every combination in a predefined set.', 'Grid search across three parameters took almost a full day to complete.', '对三个参数进行的网格搜索花了将近一整天才完成。', ARRAY['training', 'fundamentals']::text[], null, null, 203, true),
  ('ai-random-search', 'ai-research', 'random search', '随机搜索', 'n.', 'A hyperparameter tuning method that samples random combinations rather than testing every one.', 'Random search found a good configuration faster than grid search did.', '随机搜索比网格搜索更快地找到了一个不错的配置。', ARRAY['training', 'fundamentals']::text[], null, null, 204, true),
  ('ai-bayesian-optimization', 'ai-research', 'Bayesian optimization', '贝叶斯优化', 'n.', 'A hyperparameter tuning method that uses past results to intelligently choose the next configuration to try.', 'Bayesian optimization found a strong hyperparameter setting in a fraction of the trials grid search needed.', '贝叶斯优化只用了网格搜索所需试验次数的一小部分，就找到了一组不错的超参数配置。', ARRAY['training', 'fundamentals']::text[], null, null, 205, true),
  ('ai-training-pipeline', 'ai-research', 'training pipeline', '训练流水线', 'n.', 'The full sequence of automated steps used to prepare data and train a model.', 'The training pipeline handled data loading, augmentation, training, and evaluation automatically.', '这套训练流水线自动完成了数据加载、增强、训练和评估的全过程。', ARRAY['training', 'deployment']::text[], null, null, 206, true),
  ('ai-data-loader', 'ai-research', 'data loader', '数据加载器', 'n.', 'A component that efficiently feeds batches of training data to a model during training.', 'A faster data loader eliminated the GPU idle time we were seeing between batches.', '更快的数据加载器消除了我们此前在批次之间观察到的 GPU 空闲时间。', ARRAY['training', 'fundamentals']::text[], null, null, 207, true),
  ('ai-synthetic-data-generation', 'ai-research', 'synthetic data generation', '合成数据生成', 'n.', 'Creating artificial training data, often using another model, to supplement real data.', 'Synthetic data generation filled the gap where real labeled examples were scarce.', '合成数据生成弥补了真实标注样本稀缺的空缺。', ARRAY['training', 'data']::text[], null, null, 208, true),
  ('ai-domain-adaptation', 'ai-research', 'domain adaptation', '领域自适应', 'n.', 'Adapting a model trained on one data domain to perform well on a different but related domain.', 'Domain adaptation helped the model trained on news articles perform well on medical text.', '领域自适应帮助这个在新闻文章上训练的模型，在医学文本上也能表现良好。', ARRAY['training', 'fundamentals']::text[], null, null, 209, true),
  ('ai-catastrophic-forgetting', 'ai-research', 'catastrophic forgetting', '灾难性遗忘', 'n.', 'A problem where a model loses previously learned knowledge while learning a new task.', 'Catastrophic forgetting erased the model''s general knowledge after narrow fine-tuning.', '灾难性遗忘在经过狭窄领域的微调后，抹去了模型原有的通用知识。', ARRAY['training', 'fundamentals']::text[], null, null, 210, true),
  ('ai-continual-learning', 'ai-research', 'continual learning', '持续学习', 'n.', 'A model''s ability to learn new tasks over time without forgetting previously learned ones.', 'Continual learning let the model pick up new product categories without retraining from scratch.', '持续学习让模型能够学习新的产品类别，而无需从头重新训练。', ARRAY['training', 'fundamentals']::text[], null, null, 211, true),
  ('ai-active-learning', 'ai-research', 'active learning', '主动学习', 'n.', 'A training approach where the model selects the most informative examples for humans to label next.', 'Active learning cut labeling costs in half by focusing annotators on the most uncertain examples.', '主动学习让标注人员专注于模型最不确定的样本，从而把标注成本降低了一半。', ARRAY['training', 'data']::text[], null, null, 212, true),
  ('ai-weak-supervision', 'ai-research', 'weak supervision', '弱监督', 'n.', 'Training a model using noisy, imprecise, or programmatically generated labels instead of hand-labeled data.', 'Weak supervision let us generate rough labels for a million examples in a single afternoon.', '弱监督让我们在一个下午内就为一百万个样本生成了粗略的标签。', ARRAY['training', 'data']::text[], null, null, 213, true),
  ('ai-label-smoothing', 'ai-research', 'label smoothing', '标签平滑', 'n.', 'A regularization technique that softens hard labels to prevent a model from becoming overconfident.', 'Label smoothing made the model''s confidence scores more realistic and better calibrated.', '标签平滑让模型的置信度分数变得更加真实、校准得更好。', ARRAY['training', 'fundamentals']::text[], null, null, 214, true),
  ('ai-teacher-student-training', 'ai-research', 'teacher-student training', '师生训练', 'n.', 'A training setup where a smaller student model learns from the outputs of a larger teacher model.', 'Teacher-student training let the small model match much of the teacher''s accuracy.', '师生训练让这个小模型达到了与教师模型相近的准确率。', ARRAY['training', 'fundamentals']::text[], null, null, 215, true),
  ('ai-pretraining-objective', 'ai-research', 'pretraining objective', '预训练目标', 'n.', 'The specific task, such as predicting masked words, that a model optimizes during pretraining.', 'The pretraining objective was to predict the next token given everything before it.', '这个预训练目标是根据前面的所有内容来预测下一个词元。', ARRAY['training', 'llm']::text[], null, null, 216, true),
  ('ai-masked-language-modeling', 'ai-research', 'masked language modeling', '掩码语言建模', 'n.', 'A pretraining objective where a model learns to predict randomly hidden words in a sentence.', 'Masked language modeling hid fifteen percent of the words for the model to predict.', '掩码语言建模隐藏了句子中 15% 的词，让模型去预测它们。', ARRAY['training', 'nlp']::text[], null, null, 217, true),
  ('ai-contrastive-pretraining', 'ai-research', 'contrastive pretraining', '对比预训练', 'n.', 'Pretraining a model using a contrastive objective that distinguishes similar from dissimilar examples.', 'Contrastive pretraining on image-text pairs taught the model to match captions to the right photos.', '在图文对上进行的对比预训练，教会了模型将描述文字与正确的照片匹配起来。', ARRAY['training', 'fundamentals']::text[], null, null, 218, true),
  ('ai-training-instability', 'ai-research', 'training instability', '训练不稳定', 'n.', 'Erratic or divergent behavior in loss values during model training.', 'Training instability at large scale required careful tuning of the learning rate and batch size.', '大规模训练中的训练不稳定问题，需要对学习率和批大小进行细致的调整。', ARRAY['training', 'fundamentals']::text[], null, null, 219, true),
  ('ai-model-inference', 'ai-research', 'model inference', '模型推理', 'n.', 'The process of using a trained model to generate predictions on new input data.', 'Model inference ran in under a hundred milliseconds per request.', '模型推理每次请求的耗时都在一百毫秒以内。', ARRAY['inference', 'deployment']::text[], null, null, 220, true),
  ('ai-inference-latency', 'ai-research', 'inference latency', '推理延迟', 'n.', 'The amount of time it takes a model to produce an output after receiving an input.', 'Inference latency dropped by half after we switched to a quantized model.', '切换到量化模型后，推理延迟降低了一半。', ARRAY['inference', 'metrics']::text[], null, null, 221, true),
  ('ai-inference-throughput', 'ai-research', 'inference throughput', '推理吞吐量', 'n.', 'The number of requests or tokens a model can process within a given time period.', 'Inference throughput doubled once we started batching requests together.', '在开始批量处理请求之后，推理吞吐量提高了一倍。', ARRAY['inference', 'metrics']::text[], null, null, 222, true),
  ('ai-batch-inference', 'ai-research', 'batch inference', '批量推理', 'n.', 'Processing many inputs together in a single pass rather than one at a time.', 'Batch inference on the full dataset finished overnight instead of taking days.', '对整个数据集进行的批量推理只用一夜就完成了，而不是花上好几天。', ARRAY['inference', 'deployment']::text[], null, null, 223, true),
  ('ai-real-time-inference', 'ai-research', 'real-time inference', '实时推理', 'n.', 'Generating model predictions with minimal delay, suitable for interactive applications.', 'Real-time inference was essential for the live voice assistant to feel responsive.', '实时推理对于这个实时语音助手要有响应速度感至关重要。', ARRAY['inference', 'deployment']::text[], null, null, 224, true),
  ('ai-edge-inference', 'ai-research', 'edge inference', '边缘推理', 'n.', 'Running model inference directly on a local device rather than a remote server.', 'Edge inference on the camera itself meant no footage ever left the building.', '在摄像头本地进行边缘推理，意味着画面数据从未离开过大楼。', ARRAY['inference', 'deployment']::text[], null, null, 225, true),
  ('ai-inference-server', 'ai-research', 'inference server', '推理服务器', 'n.', 'A dedicated server or service optimized to run model predictions for incoming requests.', 'The inference server autoscaled to handle the spike in traffic during the product launch.', '这个推理服务器在产品发布期间的流量高峰中实现了自动扩缩容。', ARRAY['inference', 'deployment']::text[], null, null, 226, true),
  ('ai-model-serving', 'ai-research', 'model serving', '模型服务化', 'n.', 'The infrastructure and practices used to make a trained model available for inference requests.', 'Model serving through a standard API let every internal team use the same model.', '通过标准 API 进行的模型服务化，让公司内部每个团队都能使用同一个模型。', ARRAY['inference', 'deployment']::text[], null, null, 227, true),
  ('ai-kv-cache', 'ai-research', 'KV cache', 'KV 缓存', 'n.', 'A cache of previously computed attention keys and values used to speed up autoregressive generation.', 'The KV cache avoided recomputing attention for tokens that had already been generated.', 'KV 缓存避免了对已经生成过的词元重新计算注意力。', ARRAY['inference', 'llm']::text[], null, null, 228, true),
  ('ai-speculative-decoding', 'ai-research', 'speculative decoding', '推测解码', 'n.', 'A technique that uses a small, fast model to draft tokens which a larger model then verifies.', 'Speculative decoding roughly doubled the generation speed without changing the output quality.', '推测解码在不改变输出质量的前提下，把生成速度大致提高了一倍。', ARRAY['inference', 'llm']::text[], null, null, 229, true),
  ('ai-quantized-inference', 'ai-research', 'quantized inference', '量化推理', 'n.', 'Running model inference using reduced numerical precision to save memory and increase speed.', 'Quantized inference let the model run on a laptop instead of requiring a data center GPU.', '量化推理让这个模型能够在笔记本电脑上运行，而不再需要数据中心级别的 GPU。', ARRAY['inference', 'deployment']::text[], null, null, 230, true),
  ('ai-inference-optimization', 'ai-research', 'inference optimization', '推理优化', 'n.', 'Techniques applied to reduce the cost or latency of running a model in production.', 'Inference optimization cut our monthly serving costs by a third.', '推理优化让我们每月的服务成本降低了三分之一。', ARRAY['inference', 'deployment']::text[], null, null, 231, true),
  ('ai-model-compilation', 'ai-research', 'model compilation', '模型编译', 'n.', 'Converting a trained model into an optimized format for faster execution on specific hardware.', 'Model compilation for the target GPU improved throughput without any accuracy loss.', '针对目标 GPU 进行的模型编译在不损失准确率的情况下提升了吞吐量。', ARRAY['inference', 'deployment']::text[], null, null, 232, true),
  ('ai-onnx-runtime', 'ai-research', 'ONNX runtime', 'ONNX 运行时', 'n.', 'A cross-platform engine for running models exported in the ONNX format efficiently.', 'ONNX runtime let us deploy the same model across web, mobile, and server without rewriting it.', 'ONNX 运行时让我们能够在网页、移动端和服务器上部署同一个模型，而无需重写代码。', ARRAY['inference', 'deployment']::text[], null, null, 233, true),
  ('ai-inference-endpoint', 'ai-research', 'inference endpoint', '推理接口', 'n.', 'A URL or interface through which applications send requests to a deployed model.', 'The inference endpoint returned a prediction within two hundred milliseconds.', '这个推理接口能在两百毫秒内返回预测结果。', ARRAY['inference', 'deployment']::text[], null, null, 234, true),
  ('ai-streaming-output', 'ai-research', 'streaming output', '流式输出', 'n.', 'Returning a model''s generated text incrementally as it''s produced, rather than all at once.', 'Streaming output let users see the response appear word by word instead of waiting.', '流式输出让用户能够逐词看到回答的生成过程，而不需要等待完整结果。', ARRAY['inference', 'llm']::text[], null, null, 235, true),
  ('ai-token-generation-speed', 'ai-research', 'token generation speed', '词元生成速度', 'n.', 'The rate at which a language model produces output tokens, often measured per second.', 'Token generation speed reached forty tokens per second on the new hardware.', '在新硬件上，词元生成速度达到了每秒四十个词元。', ARRAY['inference', 'metrics']::text[], null, null, 236, true),
  ('ai-inference-cost', 'ai-research', 'inference cost', '推理成本', 'n.', 'The monetary or computational cost associated with running a model to generate predictions.', 'Inference cost per request dropped sharply after we adopted a smaller, distilled model.', '在采用一个更小的蒸馏模型之后，每次请求的推理成本大幅下降。', ARRAY['inference', 'metrics']::text[], null, null, 237, true),
  ('ai-model-routing', 'ai-research', 'model routing', '模型路由', 'n.', 'Directing requests to different models based on factors like cost, complexity, or capability.', 'Model routing sent simple questions to a cheap model and complex ones to a stronger one.', '模型路由把简单问题发送给了便宜的模型，把复杂问题发送给了更强的模型。', ARRAY['inference', 'deployment']::text[], null, null, 238, true),
  ('ai-load-balancing', 'ai-research', 'load balancing', '负载均衡', 'n.', 'Distributing incoming inference requests evenly across multiple servers or instances.', 'Load balancing kept any single server from becoming overwhelmed during peak traffic.', '负载均衡避免了任何一台服务器在流量高峰期被压垮。', ARRAY['inference', 'deployment']::text[], null, null, 239, true),
  ('ai-autoscaling', 'ai-research', 'autoscaling', '自动扩缩容', 'n.', 'Automatically adjusting the number of running instances based on current demand.', 'Autoscaling added extra inference servers automatically when traffic spiked.', '流量激增时，自动扩缩容会自动增加推理服务器的数量。', ARRAY['inference', 'deployment']::text[], null, null, 240, true),
  ('ai-cold-start', 'ai-research', 'cold start', '冷启动', 'n.', 'The delay experienced when a model or service must be initialized before handling its first request.', 'The cold start added almost ten seconds of delay to the first request after idle time.', '空闲一段时间后的第一次请求，冷启动会额外增加将近十秒的延迟。', ARRAY['inference', 'deployment']::text[], null, null, 241, true),
  ('ai-gpu-utilization', 'ai-research', 'GPU utilization', 'GPU 利用率', 'n.', 'The percentage of a GPU''s computational capacity actually being used.', 'Low GPU utilization suggested the model wasn''t taking full advantage of the hardware.', '较低的 GPU 利用率说明模型并没有充分利用硬件性能。', ARRAY['inference', 'metrics']::text[], null, null, 242, true),
  ('ai-inference-batching', 'ai-research', 'inference batching', '推理批处理', 'n.', 'Grouping multiple inference requests together to process them more efficiently.', 'Inference batching combined requests from different users into a single GPU pass.', '推理批处理把来自不同用户的请求合并到了同一次 GPU 计算中。', ARRAY['inference', 'deployment']::text[], null, null, 243, true),
  ('ai-output-caching', 'ai-research', 'output caching', '输出缓存', 'n.', 'Storing previously computed model outputs to avoid redundant computation for repeated inputs.', 'Output caching returned the same answer instantly the second time an identical question was asked.', '当同一个问题第二次被提出时，输出缓存能立即返回相同的答案。', ARRAY['inference', 'deployment']::text[], null, null, 244, true),
  ('ai-model-warm-up', 'ai-research', 'model warm-up', '模型预热', 'n.', 'Running a few initial requests through a model after startup to reduce latency on real requests.', 'Model warm-up before opening traffic avoided a slow first response for real users.', '在开放流量之前进行模型预热，避免了真实用户遇到较慢的首次响应。', ARRAY['inference', 'deployment']::text[], null, null, 245, true),
  ('ai-inference-pipeline', 'ai-research', 'inference pipeline', '推理流水线', 'n.', 'The sequence of preprocessing, model execution, and postprocessing steps used to serve predictions.', 'The inference pipeline resized the image, ran the model, and formatted the result automatically.', '这套推理流水线自动完成了图像缩放、模型运行和结果格式化的全过程。', ARRAY['inference', 'deployment']::text[], null, null, 246, true),
  ('ai-request-queuing', 'ai-research', 'request queuing', '请求排队', 'n.', 'Holding incoming requests in a queue until the system has capacity to process them.', 'Request queuing prevented the server from crashing during the traffic surge.', '请求排队避免了服务器在流量激增期间崩溃。', ARRAY['inference', 'deployment']::text[], null, null, 247, true),
  ('ai-concurrent-inference-requests', 'ai-research', 'concurrent inference requests', '并发推理请求', 'n.', 'Multiple inference requests being processed by a system at the same time.', 'The server handled two hundred concurrent inference requests without slowing down.', '这台服务器在处理两百个并发推理请求时依然没有出现延迟。', ARRAY['inference', 'metrics']::text[], null, null, 248, true),
  ('ai-model-offloading', 'ai-research', 'model offloading', '模型卸载', 'n.', 'Moving parts of a model''s computation to different hardware, such as CPU or disk, to save GPU memory.', 'Model offloading let the huge model run on a machine with limited GPU memory.', '模型卸载让这个庞大的模型能够在 GPU 显存有限的机器上运行。', ARRAY['inference', 'deployment']::text[], null, null, 249, true),
  ('ai-tensor-parallelism', 'ai-research', 'tensor parallelism', '张量并行', 'n.', 'Splitting individual model layers across multiple devices to run very large models.', 'Tensor parallelism split each large matrix multiplication across four GPUs.', '张量并行把每次大型矩阵乘法运算拆分到了四张 GPU 上。', ARRAY['inference', 'deployment']::text[], null, null, 250, true),
  ('ai-inference-accelerator', 'ai-research', 'inference accelerator', '推理加速器', 'n.', 'Specialized hardware designed to speed up model inference computations.', 'The inference accelerator ran the model five times faster than a general-purpose CPU.', '这个推理加速器让模型的运行速度比通用 CPU 快了五倍。', ARRAY['inference', 'deployment']::text[], null, null, 251, true),
  ('ai-hardware-acceleration', 'ai-research', 'hardware acceleration', '硬件加速', 'n.', 'Using specialized hardware, such as GPUs or TPUs, to speed up computation.', 'Hardware acceleration made training feasible in days instead of months.', '硬件加速让训练能够在几天内完成，而不是几个月。', ARRAY['inference', 'deployment']::text[], null, null, 252, true),
  ('ai-on-device-inference', 'ai-research', 'on-device inference', '端侧推理', 'n.', 'Running a model directly on a user''s device rather than sending data to a server.', 'On-device inference kept the keyboard''s autocomplete working even without an internet connection.', '端侧推理让键盘的自动补全功能即使在没有网络连接的情况下也能正常工作。', ARRAY['inference', 'deployment']::text[], null, null, 253, true),
  ('ai-inference-monitoring', 'ai-research', 'inference monitoring', '推理监控', 'n.', 'Tracking the performance, errors, and behavior of a model in production over time.', 'Inference monitoring alerted the team the moment response times started climbing.', '推理监控在响应时间刚开始上升时就立即向团队发出了警报。', ARRAY['inference', 'deployment']::text[], null, null, 254, true),
  ('ai-accuracy', 'ai-research', 'accuracy', '准确率', 'n.', 'The proportion of a model''s predictions that are correct.', 'The model reached ninety-two percent accuracy on the held-out test set.', '这个模型在留出的测试集上达到了 92% 的准确率。', ARRAY['evaluation', 'metrics']::text[], null, null, 255, true),
  ('ai-precision', 'ai-research', 'precision', '精确率', 'n.', 'The proportion of a model''s positive predictions that are actually correct.', 'High precision meant very few of the flagged transactions turned out to be false alarms.', '较高的精确率意味着被标记的交易中很少是误报。', ARRAY['evaluation', 'metrics']::text[], null, null, 256, true),
  ('ai-recall', 'ai-research', 'recall', '召回率', 'n.', 'The proportion of actual positive cases that a model correctly identifies.', 'Improving recall meant the model caught more fraud cases, even with a few more false alarms.', '提升召回率意味着模型能捕捉到更多的欺诈案例，即使会多出几个误报。', ARRAY['evaluation', 'metrics']::text[], null, null, 257, true),
  ('ai-f1-score', 'ai-research', 'F1 score', 'F1 分数', 'n.', 'A metric that balances precision and recall into a single number.', 'The F1 score was a better summary metric than accuracy for this imbalanced dataset.', '对于这个不平衡的数据集，F1 分数是比准确率更好的综合指标。', ARRAY['evaluation', 'metrics']::text[], null, null, 258, true),
  ('ai-auc-roc', 'ai-research', 'AUC-ROC', 'AUC-ROC 曲线下面积', 'n.', 'A metric that measures a classifier''s ability to distinguish between classes across all thresholds.', 'An AUC-ROC close to 1.0 indicated the model separated the two classes very well.', 'AUC-ROC 接近 1.0，说明模型很好地区分开了这两个类别。', ARRAY['evaluation', 'metrics']::text[], null, null, 259, true),
  ('ai-perplexity', 'ai-research', 'perplexity', '困惑度', 'n.', 'A metric that measures how well a language model predicts a sample of text; lower is better.', 'Perplexity dropped significantly after training on a larger, more diverse corpus.', '在更大、更多样化的语料库上训练后，困惑度显著下降了。', ARRAY['evaluation', 'metrics']::text[], null, null, 260, true),
  ('ai-bleu-score', 'ai-research', 'BLEU score', 'BLEU 分数', 'n.', 'A metric that measures how closely machine-generated text matches a set of reference translations.', 'The BLEU score improved by five points after we fine-tuned the translation model.', '在对翻译模型进行微调之后，BLEU 分数提高了五分。', ARRAY['evaluation', 'metrics']::text[], null, null, 261, true),
  ('ai-rouge-score', 'ai-research', 'ROUGE score', 'ROUGE 分数', 'n.', 'A metric used to evaluate the quality of automatically generated summaries against reference summaries.', 'The ROUGE score showed the generated summary captured most of the key points.', 'ROUGE 分数显示，生成的摘要涵盖了大部分关键要点。', ARRAY['evaluation', 'metrics']::text[], null, null, 262, true),
  ('ai-human-evaluation', 'ai-research', 'human evaluation', '人工评估', 'n.', 'Assessing model outputs using judgments from human raters rather than automated metrics.', 'Human evaluation confirmed the model''s answers were not just accurate but also easy to read.', '人工评估证实了模型的回答不仅准确，而且易于阅读。', ARRAY['evaluation', 'fundamentals']::text[], null, null, 263, true),
  ('ai-automated-evaluation', 'ai-research', 'automated evaluation', '自动化评估', 'n.', 'Assessing model outputs using programmatic metrics without human review.', 'Automated evaluation ran on every new model checkpoint without any manual effort.', '自动化评估在每个新的模型检查点上运行，完全不需要人工干预。', ARRAY['evaluation', 'fundamentals']::text[], null, null, 264, true),
  ('ai-evaluation-benchmark', 'ai-research', 'evaluation benchmark', '评估基准', 'n.', 'A standardized dataset and set of tasks used to measure and compare model performance.', 'The new model topped the evaluation benchmark that had been the industry standard for years.', '这个新模型在多年来一直是行业标准的评估基准上拿到了最高分。', ARRAY['evaluation', 'fundamentals']::text[], null, null, 265, true),
  ('ai-held-out-test-set', 'ai-research', 'held-out test set', '留出测试集', 'n.', 'A portion of data set aside and never used during training, reserved for final evaluation.', 'Performance on the held-out test set is the only number that really matters before launch.', '在上线之前，留出测试集上的表现才是唯一真正重要的数字。', ARRAY['evaluation', 'data']::text[], null, null, 266, true),
  ('ai-leaderboard', 'ai-research', 'leaderboard', '排行榜', 'n.', 'A public ranking of models based on their performance on a shared benchmark.', 'The model climbed to third place on the public leaderboard within a week of release.', '发布仅一周，这个模型就在公开排行榜上升到了第三名。', ARRAY['evaluation', 'fundamentals']::text[], null, null, 267, true),
  ('ai-error-analysis', 'ai-research', 'error analysis', '错误分析', 'n.', 'The process of examining a model''s mistakes to understand patterns and guide improvements.', 'Error analysis revealed the model consistently struggled with sarcasm.', '错误分析发现模型在处理讽刺语气时始终表现不佳。', ARRAY['evaluation', 'fundamentals']::text[], null, null, 268, true),
  ('ai-ablation-study', 'ai-research', 'ablation study', '消融实验', 'n.', 'An experiment that removes or changes one component of a model to measure its individual contribution.', 'The ablation study showed that removing the attention layer hurt performance the most.', '消融实验显示，移除注意力层对性能的损害最大。', ARRAY['evaluation', 'fundamentals']::text[], null, null, 269, true),
  ('ai-baseline-model', 'ai-research', 'baseline model', '基线模型', 'n.', 'A simple reference model used as a point of comparison for more advanced approaches.', 'The fancy new architecture barely beat the simple baseline model.', '这个花哨的新架构相较于简单的基线模型，优势并不明显。', ARRAY['evaluation', 'model']::text[], null, null, 270, true),
  ('ai-statistical-significance', 'ai-research', 'statistical significance', '统计显著性', 'n.', 'A measure of whether an observed result is unlikely to have occurred by chance.', 'The improvement wasn''t large enough to reach statistical significance.', '这次提升的幅度还不足以达到统计显著性。', ARRAY['evaluation', 'metrics']::text[], null, null, 271, true),
  ('ai-inter-annotator-agreement', 'ai-research', 'inter-annotator agreement', '标注者间一致性', 'n.', 'A measure of how much different human annotators agree when labeling the same data.', 'Low inter-annotator agreement suggested the labeling instructions were too ambiguous.', '较低的标注者间一致性说明标注说明写得太模糊了。', ARRAY['evaluation', 'data']::text[], null, null, 272, true),
  ('ai-red-teaming', 'ai-research', 'red teaming', '红队测试', 'n.', 'Deliberately probing a model with adversarial inputs to uncover weaknesses or unsafe behavior.', 'Red teaming uncovered several prompts that bypassed the model''s safety guidelines.', '红队测试发现了几个能够绕过模型安全规则的提示词。', ARRAY['evaluation', 'safety']::text[], null, null, 273, true),
  ('ai-adversarial-testing', 'ai-research', 'adversarial testing', '对抗性测试', 'n.', 'Testing a model with intentionally crafted inputs designed to cause it to fail.', 'Adversarial testing revealed the classifier could be fooled by a single altered pixel.', '对抗性测试发现，仅改变一个像素就能骗过这个分类器。', ARRAY['evaluation', 'safety']::text[], null, null, 274, true),
  ('ai-robustness-testing', 'ai-research', 'robustness testing', '鲁棒性测试', 'n.', 'Evaluating how well a model maintains performance under noisy or unexpected conditions.', 'Robustness testing checked how the model handled typos and unusual phrasing.', '鲁棒性测试检验了模型对拼写错误和非常规表达的处理能力。', ARRAY['evaluation', 'safety']::text[], null, null, 275, true),
  ('ai-bias-evaluation', 'ai-research', 'bias evaluation', '偏见评估', 'n.', 'Assessing whether a model produces systematically unfair outcomes across different groups.', 'Bias evaluation found the model performed worse on names from certain regions.', '偏见评估发现模型对某些地区的姓名处理效果较差。', ARRAY['evaluation', 'safety']::text[], null, null, 276, true),
  ('ai-fairness-metric', 'ai-research', 'fairness metric', '公平性指标', 'n.', 'A quantitative measure used to assess whether a model treats different groups equitably.', 'The fairness metric flagged a gap in approval rates between two demographic groups.', '这项公平性指标标出了两个人口群体在通过率上的差距。', ARRAY['evaluation', 'safety']::text[], null, null, 277, true),
  ('ai-calibration', 'ai-research', 'calibration', '校准', 'n.', 'How well a model''s predicted confidence scores match its actual accuracy.', 'Poor calibration meant the model was often just as confident when wrong as when right.', '校准不佳意味着模型在犯错时的置信度往往和答对时一样高。', ARRAY['evaluation', 'metrics']::text[], null, null, 278, true),
  ('ai-out-of-distribution-detection', 'ai-research', 'out-of-distribution detection', '分布外检测', 'n.', 'Identifying inputs that differ significantly from the data a model was trained on.', 'Out-of-distribution detection flagged an unusual input the model had never seen anything like.', '分布外检测标记出了一个模型此前从未见过的异常输入。', ARRAY['evaluation', 'safety']::text[], null, null, 279, true),
  ('ai-model-comparison', 'ai-research', 'model comparison', '模型对比', 'n.', 'Systematically evaluating multiple models against each other on the same tasks.', 'Model comparison across five candidates narrowed the choice down to two finalists.', '对五个候选模型进行的模型对比，最终把选择范围缩小到了两个。', ARRAY['evaluation', 'fundamentals']::text[], null, null, 280, true),
  ('ai-win-rate', 'ai-research', 'win rate', '胜率', 'n.', 'The percentage of comparisons in which a model''s output is preferred over an alternative.', 'The new model had a seventy percent win rate against the previous version.', '这个新模型相对于上一版本的胜率达到了 70%。', ARRAY['evaluation', 'metrics']::text[], null, null, 281, true),
  ('ai-pairwise-comparison', 'ai-research', 'pairwise comparison', '成对比较', 'n.', 'Evaluating two model outputs side by side to determine which one is better.', 'Pairwise comparison made it easier for raters to judge quality than scoring each answer alone.', '成对比较让评分者判断质量时比单独给每个答案打分更容易。', ARRAY['evaluation', 'fundamentals']::text[], null, null, 282, true),
  ('ai-llm-as-a-judge', 'ai-research', 'LLM-as-a-judge', '大模型评判员', 'n.', 'Using a language model itself to evaluate and score the outputs of other models.', 'LLM-as-a-judge scaled up our evaluation without needing hundreds of human raters.', '大模型评判员让我们能够扩大评估规模，而不需要数百名人工评分员。', ARRAY['evaluation', 'llm']::text[], null, null, 283, true),
  ('ai-task-specific-benchmark', 'ai-research', 'task-specific benchmark', '任务专项基准', 'n.', 'An evaluation benchmark designed to test performance on one particular type of task.', 'The task-specific benchmark for code generation revealed gaps a general benchmark had missed.', '这个针对代码生成的任务专项基准，揭示出了通用基准未能发现的差距。', ARRAY['evaluation', 'fundamentals']::text[], null, null, 284, true),
  ('ai-evaluation-harness', 'ai-research', 'evaluation harness', '评估框架', 'n.', 'The software infrastructure used to run a model through a suite of evaluation tasks.', 'The evaluation harness ran the model against forty different benchmarks overnight.', '这套评估框架在一夜之间让模型跑完了四十个不同的基准测试。', ARRAY['evaluation', 'fundamentals']::text[], null, null, 285, true),
  ('ai-regression-testing', 'ai-research', 'regression testing', '回归测试（模型层面）', 'n.', 'Re-evaluating a model after changes to confirm previously working behavior hasn''t broken.', 'Regression testing caught a case where the new model performed worse on a previously easy question type.', '回归测试发现新模型在某类此前很容易处理的问题上，表现反而变差了。', ARRAY['evaluation', 'fundamentals']::text[], null, null, 286, true),
  ('ai-qualitative-evaluation', 'ai-research', 'qualitative evaluation', '定性评估', 'n.', 'Assessing model outputs through descriptive review rather than numeric scores alone.', 'Qualitative evaluation of the transcripts revealed tone issues that metrics alone missed.', '对对话记录进行的定性评估，发现了单纯依靠指标无法察觉的语气问题。', ARRAY['evaluation', 'fundamentals']::text[], null, null, 287, true),
  ('ai-quantitative-evaluation', 'ai-research', 'quantitative evaluation', '定量评估', 'n.', 'Assessing model outputs using numeric metrics that can be measured and compared.', 'Quantitative evaluation gave leadership a clear number to track release over release.', '定量评估为管理层提供了一个可以在每次发布中持续追踪的清晰数字。', ARRAY['evaluation', 'fundamentals']::text[], null, null, 288, true),
  ('ai-evaluation-dataset', 'ai-research', 'evaluation dataset', '评估数据集', 'n.', 'A curated set of examples used specifically to measure model performance.', 'The evaluation dataset was carefully balanced across every category the model needed to handle.', '这个评估数据集在模型需要处理的每个类别之间都做了精心的平衡。', ARRAY['evaluation', 'data']::text[], null, null, 289, true),
  ('ai-training-dataset', 'ai-research', 'training dataset', '训练数据集', 'n.', 'The portion of data used to teach a model during the training process.', 'The training dataset contained two million labeled examples.', '这个训练数据集包含两百万个已标注的样本。', ARRAY['data', 'machine-learning']::text[], null, null, 290, true),
  ('ai-test-dataset', 'ai-research', 'test dataset', '测试数据集', 'n.', 'A separate portion of data used to evaluate a model''s final performance.', 'The model was never exposed to the test dataset during training.', '这个模型在训练过程中从未接触过测试数据集。', ARRAY['data', 'evaluation']::text[], null, null, 291, true),
  ('ai-data-labeling', 'ai-research', 'data labeling', '数据标注', 'n.', 'The process of assigning correct labels or categories to raw data for training purposes.', 'Data labeling for the image dataset took a team of ten annotators three weeks.', '这份图像数据集的数据标注工作，由十人组成的标注团队花了三周才完成。', ARRAY['data', 'fundamentals']::text[], null, null, 292, true),
  ('ai-data-annotation', 'ai-research', 'data annotation', '数据标注（注释）', 'n.', 'The process of adding informative tags or notes to raw data to prepare it for training.', 'Data annotation guidelines were updated after annotators disagreed on edge cases.', '在标注人员对边界情况出现分歧后，数据标注指南进行了更新。', ARRAY['data', 'fundamentals']::text[], null, null, 293, true),
  ('ai-annotation-guideline', 'ai-research', 'annotation guideline', '标注指南', 'n.', 'A document that provides rules and examples for how to label data consistently.', 'A clear annotation guideline reduced disagreements between different labelers.', '清晰的标注指南减少了不同标注人员之间的分歧。', ARRAY['data', 'fundamentals']::text[], null, null, 294, true),
  ('ai-data-pipeline', 'ai-research', 'data pipeline', '数据流水线', 'n.', 'The automated sequence of steps that moves and transforms data from source to model.', 'The data pipeline pulled fresh data every night and prepared it for the next training run.', '这条数据流水线每晚都会拉取最新数据，并为下一次训练做好准备。', ARRAY['data', 'deployment']::text[], null, null, 295, true),
  ('ai-data-cleaning', 'ai-research', 'data cleaning', '数据清洗', 'n.', 'The process of detecting and correcting errors or inconsistencies in a dataset.', 'Data cleaning removed thousands of duplicate and corrupted entries before training began.', '数据清洗在训练开始之前去除了成千上万条重复和损坏的记录。', ARRAY['data', 'fundamentals']::text[], null, null, 296, true),
  ('ai-data-preprocessing', 'ai-research', 'data preprocessing', '数据预处理', 'n.', 'The steps taken to transform raw data into a format suitable for model training.', 'Data preprocessing normalized every numeric column to the same scale.', '数据预处理把每个数值型字段都归一化到了相同的尺度。', ARRAY['data', 'fundamentals']::text[], null, null, 297, true),
  ('ai-data-augmentation', 'ai-research', 'data augmentation', '数据增强', 'n.', 'Techniques that artificially expand a training dataset by creating modified versions of existing data.', 'Data augmentation tripled the effective size of our small training set.', '数据增强让我们这个小规模训练集的有效数据量增加到了三倍。', ARRAY['data', 'training']::text[], null, null, 298, true),
  ('ai-data-imbalance', 'ai-research', 'data imbalance', '数据不平衡', 'n.', 'A situation where some classes in a dataset are much more common than others.', 'Data imbalance meant the model saw a hundred times more normal transactions than fraudulent ones.', '数据不平衡意味着模型接触到的正常交易数量是欺诈交易的一百倍。', ARRAY['data', 'fundamentals']::text[], null, null, 299, true),
  ('ai-data-sampling', 'ai-research', 'data sampling', '数据采样', 'n.', 'Selecting a representative subset of data from a larger dataset for training or analysis.', 'Data sampling kept the dataset manageable while preserving its overall distribution.', '数据采样在保留整体分布特征的同时，让数据集的规模变得可控。', ARRAY['data', 'fundamentals']::text[], null, null, 300, true),
  ('ai-data-versioning', 'ai-research', 'data versioning', '数据版本管理', 'n.', 'Tracking and managing different versions of a dataset over time.', 'Data versioning let us trace exactly which dataset version had trained each model.', '数据版本管理让我们能够精确追溯每个模型是用哪个版本的数据集训练出来的。', ARRAY['data', 'governance']::text[], null, null, 301, true),
  ('ai-data-lineage', 'ai-research', 'data lineage', '数据血缘', 'n.', 'A record of where data originated and how it has been transformed over time.', 'Data lineage traced the feature all the way back to its original raw source.', '数据血缘把这个特征一路追溯到了它最原始的数据来源。', ARRAY['data', 'governance']::text[], null, null, 302, true),
  ('ai-data-quality', 'ai-research', 'data quality', '数据质量', 'n.', 'The overall accuracy, completeness, and reliability of a dataset.', 'Poor data quality was the real reason the model kept underperforming, not the architecture.', '数据质量不佳才是模型持续表现不佳的真正原因，而不是架构问题。', ARRAY['data', 'fundamentals']::text[], null, null, 303, true),
  ('ai-data-drift', 'ai-research', 'data drift', '数据漂移', 'n.', 'A change over time in the statistical properties of the data a model receives in production.', 'Data drift meant the model trained last year no longer matched today''s user behavior.', '数据漂移意味着去年训练的模型已经不再匹配今天的用户行为。', ARRAY['data', 'deployment']::text[], null, null, 304, true),
  ('ai-concept-drift', 'ai-research', 'concept drift', '概念漂移', 'n.', 'A change over time in the underlying relationship between input data and the target outcome.', 'Concept drift explained why fraud patterns the model learned last quarter no longer applied.', '概念漂移解释了为什么模型上个季度学到的欺诈模式已经不再适用。', ARRAY['data', 'deployment']::text[], null, null, 305, true),
  ('ai-synthetic-dataset', 'ai-research', 'synthetic dataset', '合成数据集', 'n.', 'A dataset generated artificially rather than collected from real-world events.', 'The synthetic dataset simulated rare failure scenarios that almost never appeared in real logs.', '这个合成数据集模拟出了几乎不会出现在真实日志中的罕见故障场景。', ARRAY['data', 'training']::text[], null, null, 306, true),
  ('ai-crowdsourced-labeling', 'ai-research', 'crowdsourced labeling', '众包标注', 'n.', 'Collecting data labels from a large, distributed group of people rather than a small internal team.', 'Crowdsourced labeling let us annotate a hundred thousand images within a week.', '众包标注让我们能在一周之内为十万张图像完成标注。', ARRAY['data', 'fundamentals']::text[], null, null, 307, true),
  ('ai-weak-labeling', 'ai-research', 'weak labeling', '弱标注', 'n.', 'Generating approximate labels using rules or heuristics instead of careful manual annotation.', 'Weak labeling from keyword rules gave us a rough starting point before manual review.', '基于关键词规则的弱标注，在人工审核之前为我们提供了一个粗略的起点。', ARRAY['data', 'fundamentals']::text[], null, null, 308, true),
  ('ai-data-deduplication', 'ai-research', 'data deduplication', '数据去重', 'n.', 'The process of identifying and removing duplicate records from a dataset.', 'Data deduplication cut the training corpus size by fifteen percent.', '数据去重把训练语料的规模减少了 15%。', ARRAY['data', 'fundamentals']::text[], null, null, 309, true),
  ('ai-data-privacy', 'ai-research', 'data privacy', '数据隐私', 'n.', 'Practices and protections that ensure personal or sensitive data is handled responsibly.', 'Data privacy requirements meant we had to strip personal information before training.', '数据隐私要求我们在训练之前必须去除个人信息。', ARRAY['data', 'safety']::text[], null, null, 310, true),
  ('ai-anonymization', 'ai-research', 'anonymization', '匿名化', 'n.', 'The process of removing or obscuring identifying information from a dataset.', 'Anonymization replaced every customer name with a random identifier before analysis.', '匿名化在分析之前把每个客户姓名都替换成了随机标识符。', ARRAY['data', 'safety']::text[], null, null, 311, true),
  ('ai-data-governance', 'ai-research', 'data governance', '数据治理', 'n.', 'The policies and processes that ensure data is managed properly across an organization.', 'Data governance defined who was allowed to access the raw customer dataset.', '数据治理规定了谁有权限访问原始客户数据集。', ARRAY['data', 'governance']::text[], null, null, 312, true),
  ('ai-structured-data', 'ai-research', 'structured data', '结构化数据', 'n.', 'Data organized in a clearly defined format, such as tables with rows and columns.', 'Structured data from the database was much easier to work with than raw text logs.', '来自数据库的结构化数据，处理起来比原始文本日志容易得多。', ARRAY['data', 'fundamentals']::text[], null, null, 313, true),
  ('ai-unstructured-data', 'ai-research', 'unstructured data', '非结构化数据', 'n.', 'Data without a predefined format, such as free-form text, images, or audio.', 'Unstructured data like support call recordings required extra preprocessing before use.', '像客服通话录音这样的非结构化数据，在使用之前需要额外的预处理。', ARRAY['data', 'fundamentals']::text[], null, null, 314, true),
  ('ai-metadata', 'ai-research', 'metadata', '元数据', 'n.', 'Descriptive information about a dataset, such as its source, format, or collection date.', 'The metadata showed exactly when and from which source each record was collected.', '元数据清楚地显示出每条记录的采集时间和来源。', ARRAY['data', 'governance']::text[], null, null, 315, true),
  ('ai-data-schema', 'ai-research', 'data schema', '数据模式（结构定义）', 'n.', 'A formal definition of the structure, fields, and types within a dataset.', 'The data schema specified that the timestamp field had to follow a strict format.', '这份数据模式规定了时间戳字段必须遵循严格的格式。', ARRAY['data', 'fundamentals']::text[], null, null, 316, true),
  ('ai-feature-store', 'ai-research', 'feature store', '特征存储', 'n.', 'A centralized system for storing and serving reusable features across multiple models.', 'The feature store let three different teams reuse the same customer engagement features.', '这个特征存储让三个不同的团队能够复用同一套客户参与度特征。', ARRAY['data', 'deployment']::text[], null, null, 317, true),
  ('ai-data-warehouse', 'ai-research', 'data warehouse', '数据仓库', 'n.', 'A centralized repository that stores large amounts of structured data from multiple sources.', 'The data warehouse combined sales, support, and product usage data in one place.', '这个数据仓库把销售、客服和产品使用数据统一集中在了一处。', ARRAY['data', 'deployment']::text[], null, null, 318, true),
  ('ai-etl-pipeline', 'ai-research', 'ETL pipeline', 'ETL 流水线（抽取-转换-加载）', 'n.', 'A process that extracts data from sources, transforms it, and loads it into a target system.', 'The ETL pipeline ran every night to refresh the tables used for model training.', '这条 ETL 流水线每晚运行一次，用来刷新模型训练所使用的数据表。', ARRAY['data', 'deployment']::text[], null, null, 319, true),
  ('ai-data-validation', 'ai-research', 'data validation', '数据校验', 'n.', 'Automated checks that verify incoming data meets expected format and quality standards.', 'Data validation caught a batch of records with missing required fields before they reached training.', '数据校验在一批缺少必填字段的记录进入训练流程之前就发现了问题。', ARRAY['data', 'fundamentals']::text[], null, null, 320, true),
  ('ai-data-leakage', 'ai-research', 'data leakage', '数据泄漏', 'n.', 'A situation where information from outside the training set improperly influences a model.', 'Data leakage from the test set into training explained the suspiciously high accuracy.', '测试集数据泄漏到训练集中，解释了那个高得可疑的准确率。', ARRAY['data', 'evaluation']::text[], null, null, 321, true),
  ('ai-train-test-split', 'ai-research', 'train-test split', '训练-测试集划分', 'n.', 'Dividing a dataset into separate portions for training a model and evaluating it.', 'An eighty-twenty train-test split left enough data in each set for a reliable evaluation.', '80/20 的训练-测试集划分为每个数据集都留出了足够的数据量，以确保评估结果可靠。', ARRAY['data', 'evaluation']::text[], null, null, 322, true),
  ('ai-holdout-set', 'ai-research', 'holdout set', '留出集', 'n.', 'A portion of data set aside and not used in training, often for final validation.', 'The holdout set was locked away until the very end of the competition.', '这个留出集一直被封存，直到比赛的最后阶段才会用到。', ARRAY['data', 'evaluation']::text[], null, null, 323, true),
  ('ai-dataset-bias', 'ai-research', 'dataset bias', '数据集偏差', 'n.', 'A systematic skew in a dataset that causes a model to learn unfair or inaccurate patterns.', 'Dataset bias toward daytime photos made the model perform poorly on nighttime images.', '数据集偏差偏向白天拍摄的照片，导致模型在夜间图像上表现不佳。', ARRAY['data', 'safety']::text[], null, null, 324, true),
  ('ai-retrieval-augmented-generation', 'ai-research', 'retrieval-augmented generation', '检索增强生成', 'n.', 'A technique that combines a retrieval system with a language model to ground responses in external documents.', 'Retrieval-augmented generation let the assistant answer questions about documents it was never trained on.', '检索增强生成让这个助手能够回答那些它从未在训练中见过的文档相关问题。', ARRAY['rag', 'llm']::text[], null, null, 325, true),
  ('ai-vector-database', 'ai-research', 'vector database', '向量数据库', 'n.', 'A database designed to store and efficiently search high-dimensional embedding vectors.', 'The vector database returned the most relevant passages in under fifty milliseconds.', '这个向量数据库能在五十毫秒内返回最相关的段落。', ARRAY['rag', 'deployment']::text[], null, null, 326, true),
  ('ai-vector-search', 'ai-research', 'vector search', '向量搜索', 'n.', 'Searching for items by comparing the similarity of their embedding vectors.', 'Vector search found documents with similar meaning even when they used completely different words.', '向量搜索能找到含义相似的文档，即使它们使用的词语完全不同。', ARRAY['rag', 'fundamentals']::text[], null, null, 327, true),
  ('ai-semantic-search', 'ai-research', 'semantic search', '语义搜索', 'n.', 'A search approach that matches queries and documents based on meaning rather than exact keywords.', 'Semantic search returned the right support article even though the user''s wording was completely different.', '即使用户的措辞完全不同，语义搜索也能返回正确的帮助文档。', ARRAY['rag', 'fundamentals']::text[], null, null, 328, true),
  ('ai-document-chunking', 'ai-research', 'document chunking', '文档分块', 'n.', 'Splitting a long document into smaller pieces suitable for embedding and retrieval.', 'Document chunking split each manual into paragraph-sized pieces before indexing.', '文档分块在建立索引之前，把每份手册切分成了段落大小的片段。', ARRAY['rag', 'fundamentals']::text[], null, null, 329, true),
  ('ai-embedding-model', 'ai-research', 'embedding model', '嵌入模型', 'n.', 'A model trained to convert text or other data into dense vector representations.', 'The embedding model turned each sentence into a vector of seven hundred sixty-eight numbers.', '这个嵌入模型把每个句子都转换成了一个包含 768 个数字的向量。', ARRAY['rag', 'model']::text[], null, null, 330, true),
  ('ai-similarity-search', 'ai-research', 'similarity search', '相似度搜索', 'n.', 'Finding items in a dataset that are most similar to a given query based on a distance metric.', 'Similarity search surfaced the five most relevant paragraphs for the user''s question.', '相似度搜索为用户的问题找到了最相关的五个段落。', ARRAY['rag', 'fundamentals']::text[], null, null, 331, true),
  ('ai-nearest-neighbor-search', 'ai-research', 'nearest neighbor search', '最近邻搜索', 'n.', 'Finding the data points in a dataset closest to a given query point.', 'Nearest neighbor search across a million embeddings still returned results almost instantly.', '在一百万个嵌入向量中进行最近邻搜索，依然能几乎瞬间返回结果。', ARRAY['rag', 'fundamentals']::text[], null, null, 332, true),
  ('ai-reranking', 'ai-research', 'reranking', '重排序', 'n.', 'Reordering an initial set of retrieved results using a more precise, often slower, model.', 'Reranking the top fifty results with a cross-encoder noticeably improved answer quality.', '用交叉编码器对前五十条结果进行重排序，显著提升了答案质量。', ARRAY['rag', 'fundamentals']::text[], null, null, 333, true),
  ('ai-retriever', 'ai-research', 'retriever', '检索器', 'n.', 'The component in a RAG system responsible for finding relevant documents for a given query.', 'The retriever pulled the three most relevant policy documents before the model generated an answer.', '在模型生成答案之前，检索器提取出了三份最相关的政策文档。', ARRAY['rag', 'model']::text[], null, null, 334, true),
  ('ai-knowledge-base', 'ai-research', 'knowledge base', '知识库', 'n.', 'A structured or unstructured collection of information a system can retrieve from.', 'The support bot searched the company''s knowledge base before falling back to a generic answer.', '这个客服机器人会先搜索公司的知识库，然后才会退回到通用回答。', ARRAY['rag', 'data']::text[], null, null, 335, true),
  ('ai-context-injection', 'ai-research', 'context injection', '上下文注入', 'n.', 'Adding retrieved information directly into a model''s prompt to inform its response.', 'Context injection gave the model the exact policy text it needed to answer correctly.', '上下文注入把模型正确回答所需的准确政策条文提供给了它。', ARRAY['rag', 'fundamentals']::text[], null, null, 336, true),
  ('ai-grounding', 'ai-research', 'grounding', '事实依据（基于外部信息生成）', 'n.', 'Anchoring a model''s output in verifiable external information rather than relying only on memorized knowledge.', 'Grounding the response in the retrieved document reduced the chance of hallucination.', '把回答基于检索到的文档，降低了模型产生幻觉的可能性。', ARRAY['rag', 'llm']::text[], null, null, 337, true),
  ('ai-citation-generation', 'ai-research', 'citation generation', '引用生成', 'n.', 'Automatically producing references that point back to the source documents a response is based on.', 'Citation generation let users click through to verify exactly where each answer came from.', '引用生成让用户可以点击查看每个答案的确切来源。', ARRAY['rag', 'fundamentals']::text[], null, null, 338, true),
  ('ai-document-indexing', 'ai-research', 'document indexing', '文档索引', 'n.', 'The process of organizing documents into a searchable structure for fast retrieval.', 'Document indexing of the entire knowledge base took about twenty minutes.', '对整个知识库进行文档索引大约花了二十分钟。', ARRAY['rag', 'deployment']::text[], null, null, 339, true),
  ('ai-hybrid-search', 'ai-research', 'hybrid search', '混合搜索', 'n.', 'A search approach that combines keyword-based and semantic-based retrieval methods.', 'Hybrid search combined exact keyword matches with semantic similarity for better results.', '混合搜索把精确关键词匹配和语义相似度结合了起来，得到了更好的结果。', ARRAY['rag', 'fundamentals']::text[], null, null, 340, true),
  ('ai-sparse-retrieval', 'ai-research', 'sparse retrieval', '稀疏检索', 'n.', 'A retrieval method based on exact term matching, such as keyword or TF-IDF search.', 'Sparse retrieval found the exact product code faster than semantic search could.', '稀疏检索比语义搜索更快地找到了准确的产品编码。', ARRAY['rag', 'fundamentals']::text[], null, null, 341, true),
  ('ai-dense-retrieval', 'ai-research', 'dense retrieval', '密集检索', 'n.', 'A retrieval method based on comparing dense embedding vectors rather than exact keywords.', 'Dense retrieval matched the question to relevant text even without any shared keywords.', '即使没有共同的关键词，密集检索也能把问题匹配到相关的文本。', ARRAY['rag', 'fundamentals']::text[], null, null, 342, true),
  ('ai-query-expansion', 'ai-research', 'query expansion', '查询扩展', 'n.', 'Automatically adding related terms to a search query to improve retrieval results.', 'Query expansion added synonyms so the search also matched documents using different wording.', '查询扩展加入了同义词，让搜索也能匹配到使用不同措辞的文档。', ARRAY['rag', 'fundamentals']::text[], null, null, 343, true),
  ('ai-chunk-overlap', 'ai-research', 'chunk overlap', '分块重叠', 'n.', 'Sharing a portion of text between adjacent chunks to avoid losing context at chunk boundaries.', 'Chunk overlap of fifty tokens prevented a key sentence from being split across two chunks.', '五十个词元的分块重叠，避免了一个关键句子被拆分到两个不同的块中。', ARRAY['rag', 'fundamentals']::text[], null, null, 344, true),
  ('ai-retrieval-pipeline', 'ai-research', 'retrieval pipeline', '检索流水线', 'n.', 'The full sequence of steps used to find and prepare relevant information for a model.', 'The retrieval pipeline embedded the query, searched the index, and reranked the results.', '这条检索流水线依次完成了查询嵌入、索引搜索和结果重排序。', ARRAY['rag', 'deployment']::text[], null, null, 345, true),
  ('ai-index-refresh', 'ai-research', 'index refresh', '索引刷新', 'n.', 'Updating a search index to reflect new or changed documents.', 'Index refresh ran nightly so new documentation showed up in search the next morning.', '索引刷新每晚运行一次，让新文档第二天早上就能在搜索中出现。', ARRAY['rag', 'deployment']::text[], null, null, 346, true),
  ('ai-embedding-index', 'ai-research', 'embedding index', '嵌入索引', 'n.', 'A specialized data structure that stores embedding vectors for fast similarity search.', 'The embedding index made searching across ten million documents nearly instantaneous.', '这个嵌入索引让在一千万份文档中进行搜索几乎是瞬间完成的。', ARRAY['rag', 'deployment']::text[], null, null, 347, true),
  ('ai-cosine-similarity', 'ai-research', 'cosine similarity', '余弦相似度', 'n.', 'A metric that measures the angle between two vectors to determine how similar they are.', 'Cosine similarity between the two embeddings was above 0.9, indicating a strong match.', '这两个嵌入向量之间的余弦相似度超过了 0.9，说明匹配度很高。', ARRAY['rag', 'fundamentals']::text[], null, null, 348, true),
  ('ai-approximate-nearest-neighbor', 'ai-research', 'approximate nearest neighbor', '近似最近邻', 'n.', 'A fast search algorithm that finds close-enough matches instead of the exact closest match.', 'Approximate nearest neighbor search traded a tiny bit of accuracy for a huge speed gain.', '近似最近邻搜索用极小的精度损失换来了巨大的速度提升。', ARRAY['rag', 'fundamentals']::text[], null, null, 349, true),
  ('ai-knowledge-graph', 'ai-research', 'knowledge graph', '知识图谱', 'n.', 'A structured network of entities and their relationships used to represent knowledge.', 'The knowledge graph connected each product to its manufacturer, category, and related items.', '这个知识图谱把每个产品与它的制造商、类别和相关商品都关联了起来。', ARRAY['rag', 'data']::text[], null, null, 350, true),
  ('ai-retrieval-precision', 'ai-research', 'retrieval precision', '检索精确率', 'n.', 'The proportion of retrieved documents that are actually relevant to the query.', 'Retrieval precision dropped once we increased the number of chunks retrieved per query.', '在增加每次查询检索的分块数量后，检索精确率有所下降。', ARRAY['rag', 'evaluation']::text[], null, null, 351, true),
  ('ai-retrieval-recall', 'ai-research', 'retrieval recall', '检索召回率', 'n.', 'The proportion of all relevant documents that a retrieval system successfully finds.', 'Retrieval recall improved after we switched to a better embedding model.', '在切换到更好的嵌入模型之后，检索召回率有了提升。', ARRAY['rag', 'evaluation']::text[], null, null, 352, true),
  ('ai-context-relevance', 'ai-research', 'context relevance', '上下文相关性', 'n.', 'A measure of how relevant retrieved information is to the question being asked.', 'Low context relevance was the main reason the assistant''s answers went off-topic.', '较低的上下文相关性是这个助手回答跑题的主要原因。', ARRAY['rag', 'evaluation']::text[], null, null, 353, true),
  ('ai-answer-grounding', 'ai-research', 'answer grounding', '答案依据支撑', 'n.', 'Ensuring a generated answer is directly supported by the retrieved source material.', 'Answer grounding checks confirmed every claim in the response traced back to a real document.', '答案依据支撑检查确认了回答中的每一条陈述都能追溯到真实的文档。', ARRAY['rag', 'evaluation']::text[], null, null, 354, true),
  ('ai-source-attribution', 'ai-research', 'source attribution', '来源归属', 'n.', 'Identifying and crediting the specific source a piece of generated information came from.', 'Source attribution let users trust the answer because they could verify where it came from.', '来源归属让用户可以核实答案的出处，从而更加信任这个答案。', ARRAY['rag', 'fundamentals']::text[], null, null, 355, true),
  ('ai-multi-hop-retrieval', 'ai-research', 'multi-hop retrieval', '多跳检索', 'n.', 'A retrieval approach that gathers information across multiple linked steps to answer complex questions.', 'Multi-hop retrieval combined facts from two separate documents to answer the question correctly.', '多跳检索结合了两份不同文档中的信息，才正确回答了这个问题。', ARRAY['rag', 'fundamentals']::text[], null, null, 356, true),
  ('ai-retrieval-latency', 'ai-research', 'retrieval latency', '检索延迟', 'n.', 'The amount of time it takes a retrieval system to return relevant results.', 'Retrieval latency stayed under a hundred milliseconds even as the index grew.', '即使索引规模不断增长，检索延迟依然保持在一百毫秒以内。', ARRAY['rag', 'metrics']::text[], null, null, 357, true),
  ('ai-document-embedding', 'ai-research', 'document embedding', '文档嵌入', 'n.', 'A vector representation that captures the overall meaning of a full document.', 'Document embedding let us cluster thousands of articles by topic automatically.', '文档嵌入让我们能够自动把成千上万篇文章按主题聚类。', ARRAY['rag', 'model']::text[], null, null, 358, true),
  ('ai-rag-pipeline', 'ai-research', 'RAG pipeline', 'RAG 流水线', 'n.', 'The complete end-to-end system combining retrieval and generation to produce grounded answers.', 'The RAG pipeline retrieved relevant passages, then passed them to the model to generate a grounded answer.', '这条 RAG 流水线先检索出相关段落，再把它们传给模型生成有据可依的答案。', ARRAY['rag', 'deployment']::text[], null, null, 359, true),
  ('ai-agent', 'ai-research', 'AI agent', 'AI 智能体', 'n.', 'A system that uses a model to autonomously perceive, decide, and act to achieve a goal.', 'The AI agent booked the flight and hotel after being given just a one-sentence request.', '这个 AI 智能体仅凭一句话的请求，就完成了机票和酒店的预订。', ARRAY['agent', 'llm']::text[], null, null, 360, true),
  ('ai-agentic-workflow', 'ai-research', 'agentic workflow', '智能体工作流', 'n.', 'A multi-step process where a model plans and executes a sequence of actions toward a goal.', 'The agentic workflow broke the research task into five steps and completed each one in order.', '这个智能体工作流把研究任务拆解成五个步骤，并依次完成了每一个步骤。', ARRAY['agent', 'llm']::text[], null, null, 361, true),
  ('ai-tool-use', 'ai-research', 'tool use', '工具使用', 'n.', 'A model''s ability to call external tools or functions to complete a task it can''t do alone.', 'Tool use let the model check real-time weather instead of guessing based on old training data.', '工具使用让模型能够查询实时天气，而不是依据过时的训练数据来猜测。', ARRAY['agent', 'llm']::text[], null, null, 362, true),
  ('ai-function-calling', 'ai-research', 'function calling', '函数调用', 'n.', 'A model''s ability to produce structured output that triggers a specific external function.', 'Function calling let the model directly query the database instead of making up an answer.', '函数调用让模型能够直接查询数据库，而不是编造一个答案。', ARRAY['agent', 'llm']::text[], null, null, 363, true),
  ('ai-multi-agent-system', 'ai-research', 'multi-agent system', '多智能体系统', 'n.', 'A system in which multiple AI agents interact or collaborate to complete a task.', 'The multi-agent system had one agent write code and another agent review it.', '这个多智能体系统中，一个智能体负责编写代码，另一个负责审查代码。', ARRAY['agent', 'model']::text[], null, null, 364, true),
  ('ai-agent-orchestration', 'ai-research', 'agent orchestration', '智能体编排', 'n.', 'Coordinating the actions and communication of multiple agents or tools toward a shared goal.', 'Agent orchestration decided which specialized agent should handle each incoming request.', '智能体编排决定了每个进来的请求应该由哪个专门的智能体来处理。', ARRAY['agent', 'deployment']::text[], null, null, 365, true),
  ('ai-planning', 'ai-research', 'planning', '规划', 'n.', 'An agent''s process of breaking a goal down into an ordered sequence of steps.', 'Planning let the agent figure out it needed to search before it could summarize.', '规划让这个智能体意识到自己需要先搜索，然后才能进行总结。', ARRAY['agent', 'fundamentals']::text[], null, null, 366, true),
  ('ai-task-decomposition', 'ai-research', 'task decomposition', '任务分解', 'n.', 'Breaking a complex goal into smaller, more manageable sub-tasks.', 'Task decomposition split "plan the trip" into booking flights, hotels, and activities.', '任务分解把"规划这次旅行"拆分成了预订机票、酒店和活动这几项子任务。', ARRAY['agent', 'fundamentals']::text[], null, null, 367, true),
  ('ai-agent-memory', 'ai-research', 'agent memory', '智能体记忆', 'n.', 'A mechanism that lets an agent retain and recall information across steps or sessions.', 'Agent memory let the assistant remember the user''s preferences from an earlier conversation.', '智能体记忆让这个助手记住了用户在此前对话中提到的偏好。', ARRAY['agent', 'model']::text[], null, null, 368, true),
  ('ai-short-term-memory', 'ai-research', 'short-term memory', '短期记忆', 'n.', 'Information an agent retains only within the current task or conversation.', 'Short-term memory kept track of the last few messages within the same chat session.', '短期记忆记录了同一次聊天会话中最近的几条消息。', ARRAY['agent', 'model']::text[], null, null, 369, true),
  ('ai-long-term-memory', 'ai-research', 'long-term memory', '长期记忆', 'n.', 'Information an agent retains and can recall across multiple sessions over time.', 'Long-term memory let the assistant recall a preference the user had mentioned weeks earlier.', '长期记忆让这个助手能够回忆起用户几周前提到过的一个偏好。', ARRAY['agent', 'model']::text[], null, null, 370, true),
  ('ai-reflection', 'ai-research', 'reflection', '反思', 'n.', 'An agent''s process of evaluating its own previous output or actions to identify improvements.', 'Reflection let the agent notice its first answer had missed part of the question.', '反思让这个智能体意识到自己第一次的回答遗漏了问题的一部分。', ARRAY['agent', 'fundamentals']::text[], null, null, 371, true),
  ('ai-self-correction', 'ai-research', 'self-correction', '自我纠正', 'n.', 'An agent''s ability to detect and fix mistakes in its own output without human intervention.', 'Self-correction caught the calculation error and produced a revised, accurate answer.', '自我纠正发现了这个计算错误，并给出了一个修正后的准确答案。', ARRAY['agent', 'fundamentals']::text[], null, null, 372, true),
  ('ai-agent-loop', 'ai-research', 'agent loop', '智能体循环', 'n.', 'The repeated cycle of observing, deciding, and acting that drives an agent''s behavior.', 'The agent loop kept running until the task was marked complete.', '智能体循环会持续运行，直到任务被标记为完成。', ARRAY['agent', 'fundamentals']::text[], null, null, 373, true),
  ('ai-action-space', 'ai-research', 'action space', '动作空间', 'n.', 'The complete set of actions an agent is allowed to take at any given moment.', 'The action space included searching the web, reading a file, and sending a message.', '这个动作空间包括搜索网页、读取文件和发送消息。', ARRAY['agent', 'fundamentals']::text[], null, null, 374, true),
  ('ai-agent-observation', 'ai-research', 'agent observation', '智能体观测', 'n.', 'The information an agent perceives from its environment at each step.', 'The agent observation included the result of the last tool call before deciding what to do next.', '智能体观测包括了上一次工具调用的结果，用来决定下一步该做什么。', ARRAY['agent', 'fundamentals']::text[], null, null, 375, true),
  ('ai-agent-environment', 'ai-research', 'agent environment', '智能体环境', 'n.', 'The system or context an agent operates within and receives feedback from.', 'The agent environment included a sandboxed browser the agent could navigate freely.', '这个智能体环境包括了一个智能体可以自由操作的沙盒浏览器。', ARRAY['agent', 'fundamentals']::text[], null, null, 376, true),
  ('ai-reward-signal', 'ai-research', 'reward signal', '奖励信号', 'n.', 'Feedback given to an agent indicating how good or bad its recent action was.', 'The reward signal was positive whenever the agent completed a subtask correctly.', '每当智能体正确完成一个子任务时，奖励信号就会是正向的。', ARRAY['agent', 'fundamentals']::text[], null, null, 377, true),
  ('ai-agent-evaluation', 'ai-research', 'agent evaluation', '智能体评估', 'n.', 'Assessing how well an agent performs across a set of tasks or scenarios.', 'Agent evaluation measured task completion rate across fifty different scenarios.', '智能体评估在五十个不同场景中衡量了任务完成率。', ARRAY['agent', 'evaluation']::text[], null, null, 378, true),
  ('ai-autonomous-agent', 'ai-research', 'autonomous agent', '自主智能体', 'n.', 'An agent capable of operating and making decisions with little or no human intervention.', 'The autonomous agent handled the entire refund process from start to finish on its own.', '这个自主智能体独立完成了从头到尾的整个退款流程。', ARRAY['agent', 'model']::text[], null, null, 379, true),
  ('ai-human-in-the-loop', 'ai-research', 'human-in-the-loop', '人机协同（人工介入回路）', 'n.', 'A system design where a human reviews or approves an agent''s actions at key steps.', 'Human-in-the-loop approval was required before the agent could send any external email.', '在智能体发送任何外部邮件之前，都需要经过人机协同的审批环节。', ARRAY['agent', 'safety']::text[], null, null, 380, true),
  ('ai-tool-integration', 'ai-research', 'tool integration', '工具集成', 'n.', 'Connecting an agent to external tools, APIs, or services it can use to complete tasks.', 'Tool integration with the calendar API let the agent schedule meetings directly.', '与日历 API 的工具集成，让这个智能体能够直接安排会议。', ARRAY['agent', 'deployment']::text[], null, null, 381, true),
  ('ai-api-calling', 'ai-research', 'API calling', 'API 调用', 'n.', 'An agent''s action of sending a request to an external API to retrieve data or trigger an effect.', 'API calling let the agent fetch the latest stock price before answering the question.', 'API 调用让这个智能体能在回答问题之前先获取最新的股价。', ARRAY['agent', 'fundamentals']::text[], null, null, 382, true),
  ('ai-agent-framework', 'ai-research', 'agent framework', '智能体框架', 'n.', 'A software toolkit that provides the building blocks for creating and running AI agents.', 'The agent framework handled tool calling, memory, and planning out of the box.', '这个智能体框架开箱即用地处理了工具调用、记忆和规划功能。', ARRAY['agent', 'deployment']::text[], null, null, 383, true),
  ('ai-sub-agent', 'ai-research', 'sub-agent', '子智能体', 'n.', 'A specialized agent delegated a specific portion of a larger task by a parent agent.', 'The main agent spawned a sub-agent dedicated just to searching the web.', '主智能体派生出了一个专门负责网页搜索的子智能体。', ARRAY['agent', 'model']::text[], null, null, 384, true),
  ('ai-agent-handoff', 'ai-research', 'agent handoff', '智能体交接', 'n.', 'Transferring control of a task from one agent to another, more specialized agent.', 'Agent handoff passed the billing question from the general assistant to a specialized billing agent.', '智能体交接把账单相关的问题从通用助手转交给了专门的账单智能体。', ARRAY['agent', 'model']::text[], null, null, 385, true),
  ('ai-workflow-automation', 'ai-research', 'workflow automation', '工作流自动化', 'n.', 'Using agents or scripts to automatically carry out a sequence of previously manual tasks.', 'Workflow automation cut the weekly reporting process from two hours to five minutes.', '工作流自动化把每周的报告流程从两小时缩短到了五分钟。', ARRAY['agent', 'deployment']::text[], null, null, 386, true),
  ('ai-code-execution', 'ai-research', 'code execution', '代码执行', 'n.', 'An agent''s ability to run code to compute a result or verify its reasoning.', 'Code execution let the agent actually run the calculation instead of guessing the answer.', '代码执行让这个智能体能够真正运行计算，而不是凭空猜测答案。', ARRAY['agent', 'fundamentals']::text[], null, null, 387, true),
  ('ai-browsing-agent', 'ai-research', 'browsing agent', '浏览智能体', 'n.', 'An agent capable of navigating and extracting information from live web pages.', 'The browsing agent clicked through three pages to find the exact pricing details.', '这个浏览智能体点击了三个页面，才找到了准确的定价详情。', ARRAY['agent', 'model']::text[], null, null, 388, true),
  ('ai-computer-use-agent', 'ai-research', 'computer use agent', '计算机操作智能体', 'n.', 'An agent capable of directly controlling a computer interface, such as clicking and typing.', 'The computer use agent filled out the form by clicking each field, just like a person would.', '这个计算机操作智能体像人一样，逐个点击字段完成了表单填写。', ARRAY['agent', 'model']::text[], null, null, 389, true),
  ('ai-agent-guardrail', 'ai-research', 'agent guardrail', '智能体护栏', 'n.', 'A constraint or rule that limits what actions an agent is allowed to take.', 'An agent guardrail blocked any action that would delete data without explicit confirmation.', '一条智能体护栏规则拦截了任何未经明确确认就删除数据的操作。', ARRAY['agent', 'safety']::text[], null, null, 390, true),
  ('ai-agent-latency', 'ai-research', 'agent latency', '智能体延迟', 'n.', 'The total time an agent takes to complete a multi-step task.', 'Agent latency grew significantly with each additional tool call in the chain.', '每增加一次链条中的工具调用，智能体延迟就会明显增加。', ARRAY['agent', 'metrics']::text[], null, null, 391, true),
  ('ai-multi-step-reasoning', 'ai-research', 'multi-step reasoning', '多步推理', 'n.', 'An agent''s ability to work through a sequence of logical steps to reach a conclusion.', 'Multi-step reasoning let the agent solve a problem that required combining three separate facts.', '多步推理让这个智能体能够整合三条不同的事实，解决了这个问题。', ARRAY['agent', 'fundamentals']::text[], null, null, 392, true),
  ('ai-goal-directed-behavior', 'ai-research', 'goal-directed behavior', '目标导向行为', 'n.', 'Actions taken by an agent that are consistently aimed at achieving a defined objective.', 'Goal-directed behavior kept the agent focused on booking the trip despite a few dead-end searches.', '目标导向行为让这个智能体即使遇到了几次搜索死路，仍然专注于完成这次订票任务。', ARRAY['agent', 'fundamentals']::text[], null, null, 393, true),
  ('ai-agent-state', 'ai-research', 'agent state', '智能体状态', 'n.', 'The current information an agent maintains about its progress and context during a task.', 'The agent state tracked which steps of the plan had already been completed.', '智能体状态记录了计划中哪些步骤已经完成。', ARRAY['agent', 'fundamentals']::text[], null, null, 394, true),
  ('ai-ai-safety', 'ai-research', 'AI safety', 'AI 安全', 'n.', 'The field focused on ensuring AI systems behave reliably and don''t cause unintended harm.', 'The team hired its first dedicated AI safety researcher this year.', '团队今年招聘了第一位专职的 AI 安全研究员。', ARRAY['safety', 'ai-safety']::text[], null, null, 395, true),
  ('ai-ai-alignment-research', 'ai-research', 'AI alignment research', 'AI 对齐研究', 'n.', 'Research focused on ensuring AI systems pursue goals that match human values and intentions.', 'AI alignment research explored why the model sometimes optimized for the wrong objective.', 'AI 对齐研究探讨了为什么模型有时会朝着错误的目标进行优化。', ARRAY['safety', 'ai-safety']::text[], null, null, 396, true),
  ('ai-model-bias', 'ai-research', 'model bias', '模型偏见', 'n.', 'Systematic and unfair skew in a model''s predictions toward or against certain groups.', 'Model bias in hiring recommendations was discovered during a routine audit.', '在一次常规审计中发现了招聘推荐模型中存在的模型偏见。', ARRAY['safety', 'ai-safety']::text[], null, null, 397, true),
  ('ai-toxicity-detection', 'ai-research', 'toxicity detection', '毒性内容检测', 'n.', 'Automatically identifying harmful, offensive, or abusive content in text.', 'Toxicity detection flagged the comment before it was ever published publicly.', '毒性内容检测在这条评论公开发布之前就将其标记了出来。', ARRAY['safety', 'nlp']::text[], null, null, 398, true),
  ('ai-content-moderation', 'ai-research', 'content moderation', '内容审核', 'n.', 'The process of monitoring and filtering user-generated or AI-generated content for policy violations.', 'Content moderation combined automated filters with human reviewers for edge cases.', '内容审核将自动过滤器与人工审核相结合，用于处理边界情况。', ARRAY['safety', 'deployment']::text[], null, null, 399, true),
  ('ai-adversarial-attack', 'ai-research', 'adversarial attack', '对抗攻击', 'n.', 'An attempt to deceive a model by feeding it specially crafted, misleading input.', 'The adversarial attack added invisible noise that fooled the image classifier completely.', '这次对抗攻击加入了肉眼不可见的噪声，彻底欺骗了这个图像分类器。', ARRAY['safety', 'ai-safety']::text[], null, null, 400, true),
  ('ai-adversarial-example', 'ai-research', 'adversarial example', '对抗样本', 'n.', 'An input specifically designed to cause a model to make an incorrect prediction.', 'The adversarial example looked identical to a normal photo to the human eye.', '这个对抗样本在人眼看来与一张普通照片没有任何区别。', ARRAY['safety', 'ai-safety']::text[], null, null, 401, true),
  ('ai-data-poisoning', 'ai-research', 'data poisoning', '数据投毒', 'n.', 'Deliberately inserting malicious or misleading data into a training set to corrupt a model.', 'Data poisoning during training caused the model to misclassify a specific trigger pattern.', '训练过程中的数据投毒，导致模型对特定的触发模式产生了错误的分类。', ARRAY['safety', 'ai-safety']::text[], null, null, 402, true),
  ('ai-model-watermarking', 'ai-research', 'model watermarking', '模型水印', 'n.', 'Embedding a detectable signal into a model''s outputs to identify AI-generated content.', 'Model watermarking let platforms automatically flag text that had likely been generated by AI.', '模型水印让平台能够自动标记出很可能是 AI 生成的文本。', ARRAY['safety', 'ai-safety']::text[], null, null, 403, true),
  ('ai-differential-privacy', 'ai-research', 'differential privacy', '差分隐私', 'n.', 'A mathematical framework for training models while limiting what can be learned about any individual in the data.', 'Differential privacy added carefully calibrated noise so no single user''s data could be reverse-engineered.', '差分隐私加入了经过精心校准的噪声，使得任何单个用户的数据都无法被逆向还原。', ARRAY['safety', 'data']::text[], null, null, 404, true),
  ('ai-federated-learning', 'ai-research', 'federated learning', '联邦学习', 'n.', 'A training approach where models learn from data across many devices without the raw data leaving those devices.', 'Federated learning let the keyboard app improve predictions without ever uploading users'' typed messages.', '联邦学习让这个键盘应用能够改进预测效果，而无需上传用户输入的消息内容。', ARRAY['safety', 'training']::text[], null, null, 405, true),
  ('ai-membership-inference-attack', 'ai-research', 'membership inference attack', '成员推断攻击', 'n.', 'An attack that tries to determine whether a specific data record was part of a model''s training set.', 'A membership inference attack could reveal whether a particular patient''s record was used in training.', '成员推断攻击可能揭示出某位特定患者的记录是否曾被用于训练。', ARRAY['safety', 'ai-safety']::text[], null, null, 406, true),
  ('ai-model-extraction-attack', 'ai-research', 'model extraction attack', '模型提取攻击', 'n.', 'An attack that attempts to reconstruct or steal a proprietary model by querying it repeatedly.', 'The model extraction attack tried to recreate the proprietary model just by observing its outputs.', '这次模型提取攻击试图仅凭观察输出结果，就重建出这个专有模型。', ARRAY['safety', 'ai-safety']::text[], null, null, 407, true),
  ('ai-prompt-leakage', 'ai-research', 'prompt leakage', '提示词泄露', 'n.', 'When a model inadvertently reveals its confidential system prompt or internal instructions.', 'Prompt leakage exposed the exact instructions the company had given the assistant.', '提示词泄露暴露出了公司给这个助手设定的确切指令内容。', ARRAY['safety', 'llm']::text[], null, null, 408, true),
  ('ai-safety-filter', 'ai-research', 'safety filter', '安全过滤器', 'n.', 'A mechanism that blocks or modifies model outputs that violate safety guidelines.', 'The safety filter blocked the response before it ever reached the user.', '安全过滤器在这条回答到达用户之前就将其拦截了。', ARRAY['safety', 'deployment']::text[], null, null, 409, true),
  ('ai-guardrails', 'ai-research', 'guardrails', '安全护栏', 'n.', 'Rules and constraints put in place to keep an AI system''s behavior within safe boundaries.', 'The guardrails prevented the assistant from giving medical advice without a disclaimer.', '这些安全护栏防止了这个助手在没有免责声明的情况下给出医疗建议。', ARRAY['safety', 'deployment']::text[], null, null, 410, true),
  ('ai-harmful-content-detection', 'ai-research', 'harmful content detection', '有害内容检测', 'n.', 'Identifying content that could cause harm, such as violence, self-harm, or misinformation.', 'Harmful content detection routed the flagged message to a human reviewer immediately.', '有害内容检测立即将这条被标记的消息转交给了人工审核员。', ARRAY['safety', 'ai-safety']::text[], null, null, 411, true),
  ('ai-misuse-prevention', 'ai-research', 'misuse prevention', '滥用防范', 'n.', 'Measures taken to stop a system from being used for unintended or malicious purposes.', 'Misuse prevention rate-limited requests that looked like an attempt to extract training data.', '滥用防范对那些疑似试图提取训练数据的请求进行了限流处理。', ARRAY['safety', 'ai-safety']::text[], null, null, 412, true),
  ('ai-red-team-exercise', 'ai-research', 'red team exercise', '红队演练', 'n.', 'A structured exercise where a team actively tries to find weaknesses or failure modes in a system.', 'The red team exercise uncovered a way to bypass the content filter entirely.', '这次红队演练发现了一种能够完全绕过内容过滤器的方法。', ARRAY['safety', 'evaluation']::text[], null, null, 413, true),
  ('ai-responsible-ai', 'ai-research', 'responsible AI', '负责任的 AI', 'n.', 'The practice of developing and deploying AI systems in an ethical, safe, and accountable way.', 'Responsible AI principles guided every decision from data collection to deployment.', '负责任的 AI 原则指导了从数据收集到部署的每一个决策环节。', ARRAY['safety', 'governance']::text[], null, null, 414, true),
  ('ai-explainability', 'ai-research', 'explainability', '可解释性', 'n.', 'A model''s property of being understandable in terms of why it produced a given output.', 'Explainability tools showed which input features had driven the loan denial decision.', '可解释性工具展示了哪些输入特征驱动了这次贷款被拒的决定。', ARRAY['safety', 'ai-safety']::text[], null, null, 415, true),
  ('ai-interpretability', 'ai-research', 'interpretability', '可解释性研究（模型内部机制）', 'n.', 'The study of understanding the internal mechanisms behind a model''s behavior.', 'Interpretability research traced a specific behavior back to a small group of neurons.', '可解释性研究把这一特定行为追溯到了一小组神经元。', ARRAY['safety', 'ai-safety']::text[], null, null, 416, true),
  ('ai-model-transparency', 'ai-research', 'model transparency', '模型透明度', 'n.', 'The degree to which information about a model''s design, data, and limitations is openly disclosed.', 'Model transparency reports disclosed the training data sources and known limitations.', '模型透明度报告披露了训练数据的来源和已知的局限性。', ARRAY['safety', 'governance']::text[], null, null, 417, true),
  ('ai-audit-log', 'ai-research', 'audit log', '审计日志', 'n.', 'A recorded history of an AI system''s decisions and actions for later review.', 'The audit log showed exactly which model version had made each automated decision.', '审计日志清楚地记录了每一个自动化决策具体是由哪个模型版本做出的。', ARRAY['safety', 'governance']::text[], null, null, 418, true),
  ('ai-ai-governance', 'ai-research', 'AI governance', 'AI 治理', 'n.', 'The policies, standards, and oversight structures that guide the responsible use of AI.', 'AI governance required every new model to pass a review before deployment.', 'AI 治理要求每个新模型在部署前都必须通过评审。', ARRAY['safety', 'governance']::text[], null, null, 419, true),
  ('ai-risk-assessment', 'ai-research', 'risk assessment', '风险评估', 'n.', 'A structured evaluation of the potential harms and likelihood of an AI system causing them.', 'The risk assessment flagged the model''s potential for generating misleading medical information.', '风险评估指出了该模型可能生成误导性医疗信息的风险。', ARRAY['safety', 'governance']::text[], null, null, 420, true),
  ('ai-dual-use-risk', 'ai-research', 'dual-use risk', '两用风险', 'n.', 'The risk that a technology developed for beneficial purposes could also be used for harm.', 'Dual-use risk was a key concern when deciding whether to open-source the model.', '两用风险是决定是否要开源这个模型时的一个关键考量。', ARRAY['safety', 'governance']::text[], null, null, 421, true),
  ('ai-safety-evaluation', 'ai-research', 'safety evaluation', '安全评估', 'n.', 'Systematic testing of a model to measure its safety before and after deployment.', 'Safety evaluation was required before the model could be released to the public.', '在这个模型向公众发布之前，必须先完成安全评估。', ARRAY['safety', 'evaluation']::text[], null, null, 422, true),
  ('ai-deceptive-alignment', 'ai-research', 'deceptive alignment', '欺骗性对齐', 'n.', 'A hypothetical scenario where a model appears aligned during training but pursues different goals when deployed.', 'Researchers studied deceptive alignment as a long-term risk for highly capable models.', '研究人员把欺骗性对齐作为高能力模型的一项长期风险来研究。', ARRAY['safety', 'ai-safety']::text[], null, null, 423, true),
  ('ai-reward-hacking', 'ai-research', 'reward hacking', '奖励欺骗', 'n.', 'When an agent finds unintended ways to maximize its reward without achieving the intended goal.', 'Reward hacking let the agent rack up points without actually completing the task correctly.', '奖励欺骗让这个智能体在没有真正正确完成任务的情况下，也能获得大量得分。', ARRAY['safety', 'ai-safety']::text[], null, null, 424, true),
  ('ai-specification-gaming', 'ai-research', 'specification gaming', '规范博弈', 'n.', 'When a system exploits loopholes in how its objective is defined rather than solving the intended problem.', 'Specification gaming led the model to game the metric instead of genuinely improving quality.', '规范博弈让这个模型钻了评估指标的空子，而不是真正地提升质量。', ARRAY['safety', 'ai-safety']::text[], null, null, 425, true),
  ('ai-ai-incident', 'ai-research', 'AI incident', 'AI 事故', 'n.', 'An event where an AI system causes unintended harm or behaves in an unsafe way.', 'The AI incident was reported publicly along with the steps taken to prevent recurrence.', '这起 AI 事故被公开报告，并附带了防止其再次发生所采取的措施。', ARRAY['safety', 'governance']::text[], null, null, 426, true),
  ('ai-safety-guideline', 'ai-research', 'safety guideline', '安全准则', 'n.', 'A documented rule or principle intended to keep an AI system''s behavior within safe limits.', 'The safety guideline required human review before any high-risk action was taken.', '这条安全准则要求在采取任何高风险操作之前必须先经过人工审核。', ARRAY['safety', 'governance']::text[], null, null, 427, true),
  ('ai-compliance', 'ai-research', 'compliance', '监管合规', 'n.', 'Adherence to laws, regulations, and standards governing the development and use of AI systems.', 'Compliance requirements varied significantly between the regions where the product launched.', '监管合规要求在产品上线的各个地区之间存在显著差异。', ARRAY['safety', 'governance']::text[], null, null, 428, true),
  ('ai-human-oversight', 'ai-research', 'human oversight', '人工监督', 'n.', 'The practice of having people review, monitor, or intervene in an AI system''s decisions.', 'Human oversight caught a rare edge case the automated system had handled incorrectly.', '人工监督发现了一个自动化系统处理错误的罕见边界情况。', ARRAY['safety', 'governance']::text[], null, null, 429, true),
  ('ai-model-deployment', 'ai-research', 'model deployment', '模型部署', 'n.', 'The process of making a trained model available for use in a live production environment.', 'Model deployment was automated so a new version could go live within minutes of approval.', '模型部署已经实现了自动化，新版本在获批后几分钟内就能上线。', ARRAY['deployment', 'engineering']::text[], null, null, 430, true),
  ('ai-model-versioning', 'ai-research', 'model versioning', '模型版本管理', 'n.', 'Tracking and managing different iterations of a model over time.', 'Model versioning let us instantly roll back to last week''s version when the new one misbehaved.', '模型版本管理让我们能在新版本出现问题时，立即回滚到上周的版本。', ARRAY['deployment', 'engineering']::text[], null, null, 431, true),
  ('ai-model-registry', 'ai-research', 'model registry', '模型注册中心', 'n.', 'A centralized system for storing, organizing, and tracking trained models and their metadata.', 'The model registry kept a record of every metric for each model version we had trained.', '这个模型注册中心记录了我们训练过的每个模型版本的所有指标。', ARRAY['deployment', 'engineering']::text[], null, null, 432, true),
  ('ai-a-b-testing', 'ai-research', 'A/B testing', 'A/B 测试', 'n.', 'Comparing two versions of a model in production by exposing each to a portion of real traffic.', 'A/B testing showed the new model improved click-through rate by three percent.', 'A/B 测试显示新模型让点击率提升了 3%。', ARRAY['deployment', 'evaluation']::text[], null, null, 433, true),
  ('ai-canary-deployment', 'ai-research', 'canary deployment', '金丝雀部署', 'n.', 'Gradually rolling out a new model version to a small subset of traffic before a full release.', 'Canary deployment caught the regression after just one percent of traffic was affected.', '金丝雀部署在仅有 1% 的流量受到影响时，就发现了这次性能回退。', ARRAY['deployment', 'engineering']::text[], null, null, 434, true),
  ('ai-shadow-deployment', 'ai-research', 'shadow deployment', '影子部署', 'n.', 'Running a new model alongside the current one in production without affecting real user output.', 'Shadow deployment let us compare the new model''s predictions against the live model risk-free.', '影子部署让我们能够在零风险的情况下，将新模型的预测结果与线上模型进行对比。', ARRAY['deployment', 'engineering']::text[], null, null, 435, true),
  ('ai-model-rollback', 'ai-research', 'model rollback', '模型回滚', 'n.', 'Reverting a production system to a previously deployed model version.', 'Model rollback restored the previous version within two minutes of detecting the issue.', '在发现问题两分钟内，模型回滚就恢复了此前的版本。', ARRAY['deployment', 'engineering']::text[], null, null, 436, true),
  ('ai-model-monitoring', 'ai-research', 'model monitoring', '模型监控', 'n.', 'Continuously tracking a deployed model''s performance, inputs, and outputs in production.', 'Model monitoring alerted the team when prediction confidence started dropping.', '当预测置信度开始下降时，模型监控向团队发出了警报。', ARRAY['deployment', 'engineering']::text[], null, null, 437, true),
  ('ai-drift-detection', 'ai-research', 'drift detection', '漂移检测', 'n.', 'Automatically identifying when incoming data or model performance has shifted from what was expected.', 'Drift detection flagged that user queries had changed noticeably since the last training run.', '漂移检测发现自上次训练以来，用户查询已经发生了明显的变化。', ARRAY['deployment', 'engineering']::text[], null, null, 438, true),
  ('ai-performance-degradation', 'ai-research', 'performance degradation', '性能退化', 'n.', 'A decline in a model''s accuracy or effectiveness over time after deployment.', 'Performance degradation over six months made it clear the model needed retraining.', '六个月内出现的性能退化，明确表明这个模型需要重新训练。', ARRAY['deployment', 'engineering']::text[], null, null, 439, true),
  ('ai-model-retraining', 'ai-research', 'model retraining', '模型再训练', 'n.', 'Updating a model by training it again on new or additional data.', 'Model retraining every month kept predictions aligned with the latest user behavior.', '每月进行的模型再训练，让预测结果始终与最新的用户行为保持一致。', ARRAY['deployment', 'training']::text[], null, null, 440, true),
  ('ai-mlops', 'ai-research', 'MLOps', 'MLOps（机器学习运维）', 'n.', 'The set of practices for reliably and efficiently deploying and maintaining machine learning models.', 'MLOps practices turned a manual, error-prone deployment process into a repeatable pipeline.', 'MLOps 实践把一个手动、容易出错的部署流程，变成了一条可重复执行的流水线。', ARRAY['deployment', 'engineering']::text[], null, null, 441, true),
  ('ai-ci-cd-for-ml', 'ai-research', 'CI/CD for ML', '机器学习持续集成/持续部署', 'n.', 'Automated pipelines that test, build, and deploy machine learning models with every change.', 'CI/CD for ML automatically ran evaluation tests before any model could be promoted to production.', '机器学习持续集成/持续部署会在任何模型晋升到生产环境之前，自动运行评估测试。', ARRAY['deployment', 'engineering']::text[], null, null, 442, true),
  ('ai-feature-pipeline', 'ai-research', 'feature pipeline', '特征流水线', 'n.', 'The automated process that computes and delivers features to a model in production.', 'The feature pipeline computed each user''s recent activity score in real time.', '这条特征流水线实时计算出了每位用户最近的活跃度分数。', ARRAY['deployment', 'engineering']::text[], null, null, 443, true),
  ('ai-model-packaging', 'ai-research', 'model packaging', '模型打包', 'n.', 'Bundling a trained model with its dependencies into a deployable artifact.', 'Model packaging into a single container made deployment consistent across every environment.', '把模型打包成单一容器，让部署在每个环境中都保持一致。', ARRAY['deployment', 'engineering']::text[], null, null, 444, true),
  ('ai-containerization', 'ai-research', 'containerization', '容器化', 'n.', 'Packaging a model and its dependencies into an isolated, portable container for consistent deployment.', 'Containerization eliminated the "it works on my machine" problem during rollout.', '容器化消除了部署过程中"在我电脑上明明是好的"这类问题。', ARRAY['deployment', 'engineering']::text[], null, null, 445, true),
  ('ai-serving-infrastructure', 'ai-research', 'serving infrastructure', '服务基础设施', 'n.', 'The hardware and software systems responsible for running a model in production and handling requests.', 'The serving infrastructure scaled automatically to handle ten times the normal traffic.', '这套服务基础设施实现了自动扩容，以应对十倍于平时的流量。', ARRAY['deployment', 'engineering']::text[], null, null, 446, true),
  ('ai-gpu-cluster', 'ai-research', 'GPU cluster', 'GPU 集群', 'n.', 'A group of interconnected GPUs used together for training or serving large models.', 'The GPU cluster ran training jobs for multiple teams around the clock.', '这个 GPU 集群全天候为多个团队运行训练任务。', ARRAY['deployment', 'engineering']::text[], null, null, 447, true),
  ('ai-model-endpoint', 'ai-research', 'model endpoint', '模型接口端点', 'n.', 'A specific address applications use to send requests to a deployed model.', 'Each model version had its own model endpoint so old integrations kept working.', '每个模型版本都有自己独立的模型接口端点，这样旧的集成仍然可以正常工作。', ARRAY['deployment', 'engineering']::text[], null, null, 448, true),
  ('ai-api-rate-limiting', 'ai-research', 'API rate limiting', 'API 限流', 'n.', 'Restricting the number of requests a client can make within a given time period.', 'API rate limiting protected the inference server from being overwhelmed by a single client.', 'API 限流保护了这台推理服务器，避免其被单个客户端的请求压垮。', ARRAY['deployment', 'engineering']::text[], null, null, 449, true),
  ('ai-cost-optimization', 'ai-research', 'cost optimization', '成本优化', 'n.', 'Reducing the expense of running AI infrastructure while maintaining acceptable performance.', 'Cost optimization work cut monthly inference spending by forty percent.', '成本优化工作把每月的推理支出降低了 40%。', ARRAY['deployment', 'engineering']::text[], null, null, 450, true),
  ('ai-capacity-planning', 'ai-research', 'capacity planning', '容量规划', 'n.', 'Forecasting the compute resources needed to support expected future demand.', 'Capacity planning ensured enough GPUs were reserved ahead of the holiday traffic spike.', '容量规划确保了在节日流量高峰到来之前预留了足够的 GPU 资源。', ARRAY['deployment', 'engineering']::text[], null, null, 451, true),
  ('ai-multi-tenant-serving', 'ai-research', 'multi-tenant serving', '多租户服务', 'n.', 'Serving multiple customers or applications from a single shared model deployment.', 'Multi-tenant serving let dozens of clients share the same underlying model efficiently.', '多租户服务让数十个客户能够高效地共用同一个底层模型。', ARRAY['deployment', 'engineering']::text[], null, null, 452, true),
  ('ai-model-fallback', 'ai-research', 'model fallback', '模型降级方案', 'n.', 'A backup model or simpler logic used when the primary model fails or is unavailable.', 'The model fallback returned a cached response whenever the main model timed out.', '每当主模型超时，模型降级方案就会返回一个缓存好的响应。', ARRAY['deployment', 'engineering']::text[], null, null, 453, true),
  ('ai-graceful-degradation', 'ai-research', 'graceful degradation', '优雅降级', 'n.', 'Designing a system to continue functioning, at reduced capability, when part of it fails.', 'Graceful degradation meant the app still worked with simpler recommendations when the model was down.', '优雅降级意味着即使模型不可用，应用仍能以更简单的推荐方式继续运行。', ARRAY['deployment', 'engineering']::text[], null, null, 454, true),
  ('ai-deployment-pipeline', 'ai-research', 'deployment pipeline', '部署流水线', 'n.', 'The automated sequence of steps used to move a model from development into production.', 'The deployment pipeline ran tests, built the container, and pushed it to production automatically.', '这条部署流水线自动完成了测试、构建容器和推送上线的全过程。', ARRAY['deployment', 'engineering']::text[], null, null, 455, true),
  ('ai-blue-green-deployment', 'ai-research', 'blue-green deployment', '蓝绿部署', 'n.', 'A release strategy that keeps two identical environments and switches traffic between them.', 'Blue-green deployment let us switch to the new version instantly, with an instant rollback option.', '蓝绿部署让我们能瞬间切换到新版本，同时还保留了即时回滚的选项。', ARRAY['deployment', 'engineering']::text[], null, null, 456, true),
  ('ai-rollout-strategy', 'ai-research', 'rollout strategy', '发布策略', 'n.', 'A planned approach for gradually releasing a new model or feature to users.', 'The rollout strategy expanded from five percent to full traffic over a week.', '这个发布策略在一周内把流量比例从 5% 逐步扩展到了 100%。', ARRAY['deployment', 'engineering']::text[], null, null, 457, true),
  ('ai-observability', 'ai-research', 'observability', '可观测性', 'n.', 'The ability to understand a system''s internal state from its logs, metrics, and traces.', 'Good observability made it possible to diagnose the latency spike within minutes.', '良好的可观测性让我们能在几分钟内诊断出这次延迟激增的原因。', ARRAY['deployment', 'engineering']::text[], null, null, 458, true),
  ('ai-alerting', 'ai-research', 'alerting', '告警', 'n.', 'Automated notifications triggered when a monitored system behaves outside expected bounds.', 'Alerting paged the on-call engineer the moment error rates crossed the threshold.', '一旦错误率超过阈值，告警就会立即呼叫值班工程师。', ARRAY['deployment', 'engineering']::text[], null, null, 459, true),
  ('ai-incident-response', 'ai-research', 'incident response', '事故响应', 'n.', 'The coordinated process of identifying, addressing, and resolving a production issue.', 'Incident response for the model outage followed the same playbook used for any other service.', '这次模型故障的事故响应，遵循了与其他服务相同的应急预案。', ARRAY['deployment', 'engineering']::text[], null, null, 460, true),
  ('ai-production-readiness', 'ai-research', 'production readiness', '生产就绪', 'n.', 'A checklist-based assessment confirming a model or system is ready to handle real traffic.', 'Production readiness review flagged missing monitoring before the launch was approved.', '生产就绪评审在上线获批之前，发现了监控功能的缺失。', ARRAY['deployment', 'engineering']::text[], null, null, 461, true),
  ('ai-model-lifecycle', 'ai-research', 'model lifecycle', '模型生命周期', 'n.', 'The full progression of a model from development through deployment to eventual retirement.', 'The model lifecycle included stages for training, evaluation, deployment, and monitoring.', '模型生命周期包括训练、评估、部署和监控几个阶段。', ARRAY['deployment', 'engineering']::text[], null, null, 462, true),
  ('ai-experiment-tracking', 'ai-research', 'experiment tracking', '实验追踪', 'n.', 'Recording the configuration, code, and results of each model training run for later comparison.', 'Experiment tracking let us compare a hundred different training runs side by side.', '实验追踪让我们能够并排比较一百次不同的训练实验。', ARRAY['deployment', 'engineering']::text[], null, null, 463, true),
  ('ai-reproducibility', 'ai-research', 'reproducibility', '可复现性', 'n.', 'The ability to obtain the same results by rerunning an experiment under the same conditions.', 'Reproducibility was ensured by logging the exact random seed used for every training run.', '通过记录每次训练所使用的确切随机种子，保证了可复现性。', ARRAY['deployment', 'engineering']::text[], null, null, 464, true),
  ('ai-research-statement', 'ai-research', 'research statement', '研究陈述', 'n.', 'A written summary of a candidate''s past research and future research direction.', 'Her research statement outlined three concrete directions she wanted to pursue next.', '她的研究陈述概述了她接下来想要探索的三个具体方向。', ARRAY['interview', 'research']::text[], null, null, 465, true),
  ('ai-publication-record', 'ai-research', 'publication record', '发表记录', 'n.', 'A candidate''s history of published academic papers.', 'His publication record included two first-author papers at top conferences.', '他的发表记录中包括两篇发表在顶级会议上的第一作者论文。', ARRAY['interview', 'research']::text[], null, null, 466, true),
  ('ai-peer-review', 'ai-research', 'peer review', '同行评审', 'n.', 'The process by which experts in a field evaluate research before it is published.', 'The paper went through three rounds of peer review before being accepted.', '这篇论文经过了三轮同行评审之后才被接收。', ARRAY['interview', 'research']::text[], null, null, 467, true),
  ('ai-paper-submission', 'ai-research', 'paper submission', '论文投稿', 'n.', 'The act of formally sending a research paper to a conference or journal for review.', 'The paper submission deadline was pushed back by a week due to server issues.', '由于服务器故障，论文投稿的截止日期被推迟了一周。', ARRAY['interview', 'research']::text[], null, null, 468, true),
  ('ai-conference-deadline', 'ai-research', 'conference deadline', '会议截止日期', 'n.', 'The date by which a paper must be submitted to be considered for a conference.', 'The team worked through the weekend to hit the conference deadline.', '团队整个周末都在赶工，就是为了赶上这个会议截止日期。', ARRAY['interview', 'research']::text[], null, null, 469, true),
  ('ai-literature-review', 'ai-research', 'literature review', '文献综述', 'n.', 'A survey of existing research relevant to a given topic or question.', 'The literature review identified a clear gap that the new paper aimed to fill.', '文献综述发现了一个明显的空白，这篇新论文正是要填补这个空白。', ARRAY['interview', 'research']::text[], null, null, 470, true),
  ('ai-related-work', 'ai-research', 'related work', '相关工作', 'n.', 'The section of a paper that situates the research relative to prior published work.', 'The related work section compared the new method against five existing approaches.', '相关工作部分把这种新方法与五种现有方法进行了比较。', ARRAY['interview', 'research']::text[], null, null, 471, true),
  ('ai-novel-contribution', 'ai-research', 'novel contribution', '创新贡献', 'n.', 'The new idea, method, or finding that a piece of research adds to the field.', 'The novel contribution was a training technique that cut compute costs by half.', '这项创新贡献是一种能把算力成本降低一半的训练技术。', ARRAY['interview', 'research']::text[], null, null, 472, true),
  ('ai-research-hypothesis', 'ai-research', 'research hypothesis', '研究假设', 'n.', 'A proposed explanation or prediction that a research study is designed to test.', 'The research hypothesis was that larger context windows would reduce hallucination rates.', '这项研究假设认为，更大的上下文窗口能够降低幻觉发生率。', ARRAY['interview', 'research']::text[], null, null, 473, true),
  ('ai-experiment-design', 'ai-research', 'experiment design', '实验设计', 'n.', 'The planning of how a research experiment will be structured to test a hypothesis fairly.', 'Careful experiment design ruled out confounding factors that could explain the result.', '细致的实验设计排除了可能解释这一结果的混杂因素。', ARRAY['interview', 'research']::text[], null, null, 474, true),
  ('ai-grant-proposal', 'ai-research', 'grant proposal', '基金申请书', 'n.', 'A written request for funding that outlines a proposed research project.', 'The grant proposal described the budget and timeline for a two-year research project.', '这份基金申请书描述了一个为期两年的研究项目的预算和时间安排。', ARRAY['interview', 'research']::text[], null, null, 475, true),
  ('ai-open-source-contribution', 'ai-research', 'open-source contribution', '开源贡献', 'n.', 'Publicly available code, tools, or research artifacts a candidate has contributed to the community.', 'His open-source contribution to a popular training library had over a thousand stars.', '他为一个热门训练库贡献的开源代码获得了超过一千个星标。', ARRAY['interview', 'research']::text[], null, null, 476, true),
  ('ai-research-proposal', 'ai-research', 'research proposal', '研究提案', 'n.', 'A document outlining a planned research project''s goals, methods, and significance.', 'The research proposal laid out exactly how the experiments would be run.', '这份研究提案详细说明了这些实验将如何具体开展。', ARRAY['interview', 'research']::text[], null, null, 477, true),
  ('ai-thesis-defense', 'ai-research', 'thesis defense', '论文答辩', 'n.', 'A formal presentation and questioning session where a candidate defends their thesis.', 'Her thesis defense lasted two hours, including questions from the committee.', '她的论文答辩持续了两个小时，其中包括委员会的提问环节。', ARRAY['interview', 'research']::text[], null, null, 478, true),
  ('ai-research-internship', 'ai-research', 'research internship', '研究实习', 'n.', 'A temporary position focused on conducting research, often at a company or lab.', 'His research internship led to a publication he co-authored with his mentor.', '他的研究实习最终促成了一篇与导师合作发表的论文。', ARRAY['interview', 'research']::text[], null, null, 479, true),
  ('ai-research-collaboration', 'ai-research', 'research collaboration', '研究合作', 'n.', 'A joint research effort between two or more individuals or institutions.', 'The research collaboration between the two labs combined expertise in vision and language.', '这两个实验室之间的研究合作，结合了视觉和语言两个领域的专长。', ARRAY['interview', 'research']::text[], null, null, 480, true),
  ('ai-co-author', 'ai-research', 'co-author', '共同作者', 'n.', 'A person who jointly contributes to and is credited on a research paper.', 'She was a co-author on the paper alongside three other researchers.', '除她之外，这篇论文还有另外三位共同作者。', ARRAY['interview', 'research']::text[], null, null, 481, true),
  ('ai-research-impact', 'ai-research', 'research impact', '研究影响力', 'n.', 'The measurable effect a piece of research has had on its field or on real-world applications.', 'The paper''s research impact was clear from how many later works built directly on it.', '从后续有多少研究直接基于这篇论文展开就能看出它的研究影响力。', ARRAY['interview', 'research']::text[], null, null, 482, true),
  ('ai-citation-count', 'ai-research', 'citation count', '引用次数', 'n.', 'The number of times a research paper has been referenced by other publications.', 'The citation count for the paper passed a thousand within three years.', '这篇论文的引用次数在三年内就突破了一千次。', ARRAY['interview', 'research']::text[], null, null, 483, true),
  ('ai-state-of-the-art', 'ai-research', 'state of the art', '最先进水平', 'n.', 'The current best-known level of performance or technique in a given field.', 'The new model set a new state of the art on the benchmark.', '这个新模型在该基准测试上创下了新的最先进水平。', ARRAY['interview', 'research']::text[], null, null, 484, true),
  ('ai-research-question', 'ai-research', 'research question', '研究问题', 'n.', 'The specific question a piece of research is designed to answer.', 'She started every project by writing down a single, clear research question.', '她开始每个项目时都会先写下一个清晰明确的研究问题。', ARRAY['interview', 'research']::text[], null, null, 485, true),
  ('ai-limitations', 'ai-research', 'limitations', '局限性', 'n.', 'The known weaknesses or boundaries of a piece of research, often disclosed by the authors themselves.', 'The paper''s limitations section honestly noted the method hadn''t been tested at scale.', '这篇论文的局限性部分坦诚地指出该方法尚未在大规模场景下经过测试。', ARRAY['interview', 'research']::text[], null, null, 486, true),
  ('ai-future-work', 'ai-research', 'future work', '未来工作', 'n.', 'Directions for further research suggested at the end of a paper.', 'The future work section proposed extending the method to multilingual settings.', '未来工作部分提出了将这种方法扩展到多语言场景的设想。', ARRAY['interview', 'research']::text[], null, null, 487, true),
  ('ai-technical-interview', 'ai-research', 'technical interview', '技术面试', 'n.', 'An interview stage that evaluates a candidate''s technical knowledge and problem-solving skills.', 'The technical interview included a live coding exercise and a research discussion.', '这次技术面试包括了一个实时编程环节和一次研究讨论。', ARRAY['interview', 'research']::text[], null, null, 488, true),
  ('ai-whiteboard-coding', 'ai-research', 'whiteboard coding', '白板编程', 'n.', 'Writing and explaining code by hand, often on a whiteboard, during a technical interview.', 'Whiteboard coding tested how she communicated her reasoning, not just whether the code ran.', '白板编程考察的是她如何清晰表达自己的思路，而不仅仅是代码能否运行。', ARRAY['interview', 'research']::text[], null, null, 489, true),
  ('ai-paper-presentation', 'ai-research', 'paper presentation', '论文报告', 'n.', 'A talk given to present research findings to an audience, often at a conference.', 'His paper presentation at the conference drew a packed room of researchers.', '他在会议上的论文报告吸引了满满一屋子的研究人员。', ARRAY['interview', 'research']::text[], null, null, 490, true),
  ('ai-research-portfolio', 'ai-research', 'research portfolio', '研究作品集', 'n.', 'A curated collection of a candidate''s research projects, papers, and contributions.', 'Her research portfolio spanned three different subfields of machine learning.', '她的研究作品集涵盖了机器学习的三个不同子领域。', ARRAY['interview', 'research']::text[], null, null, 491, true),
  ('ai-independent-research', 'ai-research', 'independent research', '独立研究', 'n.', 'Research conducted with significant autonomy, often without close supervision.', 'His independent research during graduate school led to his first solo-authored paper.', '他在研究生阶段的独立研究，促成了他的第一篇独立作者论文。', ARRAY['interview', 'research']::text[], null, null, 492, true),
  ('ai-research-mentorship', 'ai-research', 'research mentorship', '科研指导', 'n.', 'Guidance and support provided by an experienced researcher to someone earlier in their career.', 'Research mentorship from her advisor shaped how she approached experiment design.', '导师的科研指导塑造了她设计实验的方式。', ARRAY['interview', 'research']::text[], null, null, 493, true),
  ('ai-cross-disciplinary-research', 'ai-research', 'cross-disciplinary research', '跨学科研究', 'n.', 'Research that draws on methods or knowledge from more than one academic field.', 'Cross-disciplinary research combining neuroscience and machine learning led to the new architecture.', '结合神经科学和机器学习的跨学科研究，催生出了这种新架构。', ARRAY['interview', 'research']::text[], null, null, 494, true),
  ('ai-reading-group', 'ai-research', 'reading group', '论文阅读小组', 'n.', 'A recurring meeting where researchers discuss recent papers together.', 'The weekly reading group kept the whole team current on the latest published work.', '每周一次的论文阅读小组，让整个团队都能及时了解最新发表的研究。', ARRAY['interview', 'research']::text[], null, null, 495, true),
  ('ai-research-trajectory', 'ai-research', 'research trajectory', '研究发展轨迹', 'n.', 'The overall direction and progression of a researcher''s work over time.', 'Her research trajectory moved from pure theory toward more applied, deployable systems.', '她的研究发展轨迹从纯理论逐渐转向了更偏应用、可落地的系统。', ARRAY['interview', 'research']::text[], null, null, 496, true),
  ('ai-research-career-path', 'ai-research', 'research career path', '科研职业路径', 'n.', 'The typical progression of roles and milestones in an academic or industrial research career.', 'He asked the interviewer to describe the research career path from scientist to senior scientist.', '他向面试官询问了从科学家到高级科学家的科研职业路径。', ARRAY['interview', 'research']::text[], null, null, 497, true),
  ('ai-research-vision', 'ai-research', 'research vision', '研究愿景', 'n.', 'A candidate''s long-term view of the problems they want to solve and why they matter.', 'Her research vision centered on making powerful models safer to deploy.', '她的研究愿景聚焦于让强大的模型能够更安全地部署应用。', ARRAY['interview', 'research']::text[], null, null, 498, true),
